(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["vi"] = {"ui":{"skip":"Bỏ qua, đến nội dung","back":"← Quay lại AI-gile","lang.button":"Ngôn ngữ: {name}","lang.dialog":"Chọn một ngôn ngữ","lang.search":"Tìm ngôn ngữ","lang.none":"Không có ngôn ngữ nào khớp","lang.notYet":"{name} chưa được dịch","theme.aria":"Đổi giao diện: sáng, tối hoặc đen","theme.toLight":"Chuyển sang giao diện sáng","theme.toDark":"Chuyển sang giao diện tối","theme.toBlack":"Chuyển sang giao diện đen (đen tuyền, dịu mắt trên màn hình OLED)","words.underline":"Gạch chân những từ này trên trang","words.underlineHelp":"Di chuột hoặc chạm vào một từ có gạch chấm để xem nghĩa của nó.","words.col.todo":"Các thẻ được chọn cho lúc này: nhóm sẽ bắt đầu với những thẻ này tiếp theo.","words.col.doing":"Một AI đang làm thẻ này ngay lúc này.","words.col.review":"Một AI đã làm xong; một AI khác kiểm tra trước khi đến tay bạn.","words.col.verify":"Đang chờ bạn: hãy thử và cho biết nó có chạy không.","words.col.team":"Ghi chú hoặc câu trả lời của bạn, đang chờ nhóm nhận.","words.col.done":"Đã xong và được chấp nhận.","index.title":"AI-gile: nhóm lập trình AI của bạn, trên một bảng","index.description":"AI-gile là bảng kanban cho các nhóm lập trình bằng AI. Họ làm việc khi bạn ngủ; bạn chỉ nhận một chồng ngắn những việc cần quyết định, thử và chấp nhận.","hero.logoAlt":"Biểu tượng bảng AI-gile","hero.h1.html":"Nhóm lập trình AI của bạn, trên một&nbsp;bảng.","hero.alpha":"🐣 Tiền alpha kín","hero.alphaTitle":"Còn sớm và chưa xong: cảm ơn bạn đã thử!","hero.lede":"Họ làm trong lúc bạn ngủ. Sáng ra bạn nhận một chồng ngắn: vài câu hỏi, vài thứ cần thử, một hai viên kim cương tím. Bấm, chấp nhận, rồi quay lại với ly cà phê.","dl.windows":"Ứng dụng Windows","dl.browser":"Chạy trong trình duyệt","dl.messenger":"📱 Messenger cho điện thoại","dl.soon":"Sắp ra mắt","dl.notify":"🔔 Báo cho tôi khi mở","dl.notifySmall":"Alpha hoặc beta","hero.secondary":"Agile, nhưng nhóm không bao giờ cần cà phê họp đứng. (Họ vẫn họp đứng thôi.)","pitch.h2":"AI-gile trong bao nhiêu từ tùy bạn","pitch.lede":"Chọn một độ dài, từ một từ đến 144. Mỗi độ dài là một bản mô tả riêng, viết cho đúng cỡ đó. Kéo thanh trượt hoặc dùng phím mũi tên.","pitch.rangeLabel":"Độ dài tính bằng từ","pitch.dice":"🎲 một bản khác","pitch.words.one":"{n} từ","pitch.words.other":"{n} từ","pitch.letters.one":"{n} chữ cái","pitch.letters.other":"{n} chữ cái","pitch.chars.one":"{n} ký tự","pitch.chars.other":"{n} ký tự","count.line.html.one":"{n} thẻ trên bảng ngay lúc này","count.line.html.other":"{n} thẻ trên bảng ngay lúc này","people.humans.html.one":"👥 {n} người","people.humans.html.other":"👥 {n} người","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agent","people.working.html.one":"⚡ {n} đang làm việc ngay lúc này","people.working.html.other":"⚡ {n} đang làm việc ngay lúc này","pre.title":"AI-gile: có gì đó đang được xây","pre.description":"Có gì đó đang được xây ở đây: một bảng nơi các nhóm AI xây những gì bạn yêu cầu, và dạy bạn trong lúc làm. Hiện là bản tiền alpha kín cùng bạn bè.","pre.h1":"Có gì đó đang được xây ở đây. 🤫","pre.line":"Một bảng nơi các nhóm AI xây những gì bạn yêu cầu, và dạy bạn trong lúc làm. Hiện là bản tiền alpha kín cùng bạn bè.","pre.btn":"🔔 Báo cho tôi khi mở","pre.peek":"Sau lớp kính: bảng thật, trực tiếp. Mỗi thẻ là một thanh màu.","pre.peekFake":"Sau lớp kính: một bảng đang làm việc trông như thế này.","pre.night":"🌙 Người gác đêm đang phụ trách · 😴 con người đang nghỉ ngơi","features.aria":"Nó làm gì","f.pile.h":"Một chồng dành cho bạn","f.pile.html":"<b>Cho bạn</b> gom mọi thứ đang chờ bạn ở tất cả dự án: câu hỏi, thứ cần thử, việc chỉ con người làm được. Hàng đợi cho biết việc tiếp theo là gì và mất bao lâu.","f.sleep.h":"Những nhóm làm việc khi bạn ngủ","f.sleep.p":"Mỗi dự án có một trưởng nhóm và một nhóm agent AI. Viết bình luận vào thẻ, nhóm sẽ thức dậy, làm việc, rồi giao lại kèm các bước mà một người mệt mỏi cũng làm theo được.","f.tester.h":"Một người kiểm thử AI xem trước","f.tester.p":"Trước khi gì đó đến tay bạn, người kiểm thử làm theo các bước trong một bản sao của ứng dụng và cho xem điều đã thấy, kèm ảnh chụp màn hình. Lướt qua những thẻ đã đạt và chấp nhận bằng một cú bấm.","f.proof.h":"Bằng chứng, không phải lời hứa","f.proof.p":"Mỗi lần bàn giao đều cho thấy điều gì đã đổi: các tệp, phần khác biệt, ảnh chụp màn hình. Không cần mở từng ứng dụng để xem đã xong chưa.","f.chat.h":"Trò chuyện với các trưởng nhóm","f.chat.p":"Một thanh bên kiểu Discord: mỗi dự án một biểu tượng, kim cương tím cho việc cần bạn. Nhắn cho trưởng nhóm một ý tưởng; họ biến nó thành thẻ và kế hoạch, kèm nút ✅ Bắt đầu.","f.tidy.h":"Tự giữ cho gọn gàng","f.tidy.p":"Các thẻ liên quan gộp thành một, tiêu đề rối được sửa lại, và phần kiểm tra token giữ cho mã gọn nhẹ. Ít thứ phải chuyển qua lại, ít thứ phải nghĩ hơn.","f.private.h":"Của bạn, trên máy tính của bạn","f.private.li1":"Bảng chạy ngay trên máy của bạn và chỉ trả lời bạn.","f.private.li2":"Tin nhắn riêng giữa mọi người được mã hóa đầu cuối.","f.private.li3":"Không tài khoản, không trình theo dõi, không cookie.","f.lang.h":"Bằng ngôn ngữ của bạn","f.lang.p":"Hơn 120 ngôn ngữ, từ tiếng Hà Lan, xứ Wales và Nhật đến tiếng cướp biển, Yoda và Klingon, kèm nút chuyển nhanh về tiếng Anh cho các thuật ngữ chuyên ngành.","f.service.h":"Từ một ý tưởng đến một dịch vụ thật","f.service.p":"Đã làm ra thứ gì đó với AI và giờ có người dùng? Đánh dấu nó là dịch vụ và bảng sẽ giúp bạn vận hành nó thật tốt: kiểm tra uptime, trang trạng thái công khai, sự cố có bản tổng kết, thay đổi cần một lần Go, sao lưu được kiểm tra hằng ngày. Phần Trợ giúp hướng dẫn từng bước khi bạn làm tới.","msgr.h2":"AI-gile Messenger: cả đội trong túi bạn","msgr.p1":"Trò chuyện với đội AI của bạn mà không cần mở bảng. Nhắn tin với các trưởng dự án và bạn bè, xem các bước kiểm thử của một thẻ và trả lời, tất cả ngay trên điện thoại.","msgr.p2":"Để ghép nối, hãy quét mã QR trên bảng của bạn. Lần đầu dùng? Một cuộc trò chuyện demo thân thiện sẽ dẫn bạn đi một vòng.","msgr.when":"Android trước, sau đó là bản web cho điện thoại và iPhone.","msgr.who":"Trưởng dự án của bạn","msgr.b1":"Bản sửa chế độ tối đã xong. Bạn muốn xem các bước kiểm thử không?","msgr.b2":"Có, cho mình xem nhé!","msgr.b3":"1. Mở Cài đặt. 2. Chọn Tối. Trông ổn chưa?","tl.aria":"Dòng thời gian từ cuộc trò chuyện đầu tiên đến lộ trình","tl.h2":"Từ cuộc trò chuyện đầu tiên đến điều tiếp theo","tl.lede":"Ngày giờ thật, theo múi giờ của bạn. Sau hôm nay là kế hoạch, không hứa ngày nào.","tl.today":"Hôm nay","tl.planned":"dự kiến","tl.doing":"đang làm","tl.cards.one":"{n} thẻ","tl.cards.other":"{n} thẻ","join.h2":"Cùng tham gia","join.lede":"AI-gile đang được xây bởi một gã râu ria lập dị có AuDHD và vài trận chiến với sức khỏe tinh thần, cùng rất nhiều agent kiên nhẫn. Hiện còn riêng tư, trong bản alpha kín với bạn bè. Muốn thử khi nó mở ra không?","join.btn":"Đăng ký quan tâm","join.small":"Chúng tôi sẽ gửi email cho bạn, không gì khác","footer.tag":"AI-gile. Không trình theo dõi, không cookie, không cà phê họp đứng.","footer.licence":"Giấy phép doanh nghiệp","footer.status":"Trạng thái","footer.privacy":"Chúng tôi giữ những gì","footer.thanks":"Cuộc gọi nhờ có ChilledChat","form.sending":"Đang gửi…","form.failed":"Không được rồi: hãy thử lại sau.","form.offline":"Không kết nối được với AI-gile: hãy thử lại sau.","form.keep":"Chúng tôi chỉ dùng thông tin này để trả lời bạn, rồi xóa đi. Không trình theo dõi, không cookie.","form.keepLink":"Chúng tôi giữ những gì","interest.title":"AI-gile: báo cho tôi khi alpha mở","interest.description":"Để lại email để biết khi nào bản alpha hoặc beta kín của AI-gile mở ra.","interest.h1":"🔔 Báo cho tôi khi mở","interest.lede":"AI-gile đang ở giai đoạn tiền alpha kín. Để lại email, chúng tôi sẽ viết đúng một lần, khi có chỗ cho bạn.","interest.email":"Email của bạn","interest.which":"Bản thử nào?","interest.alpha":"Alpha kín: sớm, còn thô, thay đổi nhiều","interest.beta":"Beta: ổn định hơn, muộn hơn","interest.both":"Bản nào đến trước cũng được","interest.submit":"Ghi tên tôi vào danh sách","interest.thanks":"Cảm ơn bạn! Bạn đã có tên trong danh sách.","licence.title":"AI-gile: giấy phép doanh nghiệp","licence.description":"Dùng AI-gile cho công việc kinh doanh? Hãy đăng ký giấy phép doanh nghiệp miễn phí.","licence.h1":"📜 Giấy phép doanh nghiệp","licence.lede":"Dùng AI-gile ở chỗ làm? Hãy cho chúng tôi biết bạn là ai và làm gì. Nếu việc đó mang lại chút điều tốt, giấy phép là miễn phí.","licence.company":"Công ty","licence.website":"Trang web","licence.what":"Bạn làm gì","licence.how":"Nó giúp ích cho thế giới thế nào","licence.email":"Email","licence.submit":"Đăng ký","licence.thanks":"Cảm ơn bạn! Chúng tôi sẽ trả lời qua email.","status.title":"Trạng thái AI-gile","status.h1":"Trạng thái AI-gile","status.quiet":"Mọi thứ yên ắng","status.intro":"AI-gile có đang hoạt động không? Trang này kiểm tra trang web, chia sẻ bảng, cuộc gọi và bản tải xuống mỗi 5 phút.","status.up":"Đang hoạt động (phản hồi trong {ms} ms)","status.slow":"Không phản hồi lần kiểm tra gần nhất, đang thử lại","status.down":"Ngừng hoạt động: không phản hồi hai lần kiểm tra gần nhất","status.svc.web":"Trang web","status.svc.web.offers":"Trang này: AI-gile là gì, và biểu mẫu “Báo cho tôi khi mở”","status.svc.boards":"Chia sẻ bảng","status.svc.boards.offers":"Bảng công khai, tin nhắn giữa bạn bè và lời mời","status.svc.calls":"Cuộc gọi","status.svc.calls.offers":"Thoại, video và chia sẻ màn hình trong AI-gile","status.svc.download":"Tải xuống","status.svc.download.offers":"Bộ cài đặt Windows và liên kết mời","status.checking":"Đang kiểm tra…","status.offline":"Hiện chưa kết nối được dịch vụ trạng thái (đang thử lại)","status.updated":"cập nhật {ago}","status.justNow":"vừa xong","status.min":"{n} phút trước","status.hours":"{n} giờ trước","status.days":"{n} ngày trước","privacy.title":"AI-gile: chúng tôi giữ những gì","privacy.h1":"Chúng tôi giữ những gì","privacy.lede":"Nói ngắn gọn: chỉ những gì bạn gửi cho chúng tôi, và không giữ lâu.","privacy.only":"Chỉ những gì bạn gửi cho chúng tôi: những gì bạn nhập vào biểu mẫu, như email của bạn. Ngoài ra không có gì khác về bạn.","privacy.sealed":"Dữ liệu được niêm phong để máy chủ của chúng tôi không đọc được: ngay trong trình duyệt của bạn trước khi gửi đi (với trình duyệt cũ hơn thì ngay khi đến nơi). Chỉ bảng của chính chúng tôi mới mở được.","privacy.server":"Dữ liệu bị xóa khỏi máy chủ ngay khi đến bảng của chúng tôi. Thứ gì còn sót lại sau 30 ngày cũng sẽ bị xóa.","privacy.board":"Chúng tôi chỉ giữ nó trên bảng cho đến khi đã trả lời bạn, rồi xóa luôn ở đó.","privacy.none":"Không trình theo dõi, không cookie, không phân tích.","privacy.local":"Ngôn ngữ và lựa chọn giao diện sáng hay tối của bạn chỉ nằm trong trình duyệt của bạn. Chúng không bao giờ được gửi cho chúng tôi.","privacy.ask":"Muốn xóa sớm hơn? Hãy trả lời email của chúng tôi và nói vậy.","live.h2":"Xem nó được xây dựng, trực tiếp","live.caption":"Mọi thẻ đều được ẩn: bạn thấy hình dạng của công việc, không phải câu chữ.","live.watching.one":"trực tiếp: {n} người đang xem","live.watching.other":"trực tiếp: {n} người đang xem","live.last.now":"Thẻ cuối cùng vừa được chuyển xong","live.last.min.one":"Thẻ cuối cùng được chuyển {n} phút trước","live.last.min.other":"Thẻ cuối cùng được chuyển {n} phút trước","live.last.hour.one":"Thẻ cuối cùng được chuyển {n} giờ trước","live.last.hour.other":"Thẻ cuối cùng được chuyển {n} giờ trước","live.last.day.one":"Thẻ cuối cùng được chuyển {n} ngày trước","live.last.day.other":"Thẻ cuối cùng được chuyển {n} ngày trước","live.offline":"Bảng trực tiếp đang nghỉ một chút. Hãy quay lại sớm nhé.","live.cols":"Backlog|Cần làm|Đang làm|Nhóm kiểm tra|Bạn cần test|Cho nhóm|Xong"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Agent."]},{"n":2,"texts":["Kanban robot.","Giao agent.","Việc xong."]},{"n":3,"texts":["Kanban cho robot.","Ý thành tính năng.","Kanban agent miễn phí."]},{"n":5,"texts":["Bảng kanban do agent vận hành.","Bạn viết thẻ. Agent làm.","Miễn phí, tại máy, hơi ngộ."]},{"n":8,"texts":["Bảng kanban miễn phí, nơi các agent AI làm việc.","Viết ý tưởng. Agent làm ra. Bạn chấp nhận.","Agile cho một con người và nhiều robot kiên nhẫn."]},{"n":13,"texts":["Một bảng kanban trên máy bạn, nơi các agent AI nhận thẻ về làm.","Viết một ý tưởng. Một nhóm agent làm ra. Người kiểm thử xem lại.","Miễn phí, không tài khoản, không theo dõi: một bảng, vài robot, và bạn làm chủ."]},{"n":21,"texts":["AI-gile là bảng kanban để làm việc cùng các agent lập trình AI. Họ nhận thẻ về làm; bạn thử và chấp nhận chúng.","Mỗi dự án có một trưởng nhóm và các agent AI. Bình luận vào thẻ bất kỳ, cả nhóm bắt tay vào việc.","Một bảng việc cần làm cá nhân, miễn phí, chạy ngay trên máy bạn. Người làm là robot. Người gật đầu là bạn."]},{"n":34,"texts":["Bạn đặt ý tưởng lên bảng. Một nhóm agent AI biến chúng thành tính năng chạy được, kiểm thử, rồi giao lại kèm các bước để thử. Chưa gì được tính là xong cho đến khi bạn nói vậy.","AI-gile là bảng kanban tự chế mà Rich làm với rất nhiều sự giúp đỡ của chính các agent mà nó đang quản lý. Miễn phí, chạy trên máy bạn, và chia sẻ cho bạn bè chứ không bán.","Hình dung một bảng kanban bình thường, với các cột từ Backlog đến Xong, chỉ khác là thẻ do các agent AI nhận làm. Họ báo cáo tiến độ, hỏi khi bị kẹt, và luôn chờ bạn giơ ngón tay cái."]},{"n":55,"texts":["AI-gile là một bảng kanban mà cả nhóm đều là agent AI. Mỗi dự án có một trưởng nhóm lên kế hoạch công việc và những người trợ giúp làm ra nó. Khi một tính năng sẵn sàng, một người kiểm thử AI thử nó và chụp màn hình, rồi nó rơi vào chồng của bạn. Chấp nhận, hoặc bình luận để họ làm lại.","Nó bắt đầu từ cách một người theo dõi cùng lúc thật nhiều phiên lập trình AI, rồi lớn thành một chiếc bảng đúng nghĩa. Nó chạy trên máy bạn, không cần tài khoản, không có trình theo dõi. Miễn phí cho bạn bè và những ai tò mò. Nó cũng chưa xong, nên hãy chờ vài chỗ gồ ghề và đôi bất ngờ.","Đây là phiên bản thành thật. Bạn vẫn phải có ý tưởng, và vẫn phải kiểm tra kết quả. Việc AI-gile làm là mọi thứ ở giữa: giữ các thẻ có thứ tự, đánh thức đúng agent khi bạn bình luận, cho thấy chính xác điều gì đã đổi, và gom tất cả vào một chồng ngắn dành cho bạn."]},{"n":89,"texts":["AI-gile là một bảng kanban miễn phí chạy ngay trên máy tính của bạn. Thay vì con người, mỗi dự án có một nhóm agent AI: một trưởng nhóm biến ý tưởng của bạn thành thẻ và kế hoạch, cùng những người trợ giúp nhận thẻ theo thứ tự ưu tiên. Khi có thứ gì đó làm xong, một người kiểm thử AI làm theo các bước thử và cho bạn xem điều đã thấy. Rồi nó chờ trong một chồng mang tên Cho bạn. Bạn chấp nhận, hoặc bình luận và cả nhóm thử lại. Không có gì đến được cột Xong nếu thiếu bạn.","Có vài tính năng bạn có thể không ngờ tới. Một người gác đêm giữ cột Cần làm luôn đầy khi bạn ngủ, chọn những thẻ không cần bạn trả lời. Bộ đếm token cho thấy các agent đã dùng bao nhiêu hôm nay và tuần này, còn Chế độ Không Token bảo họ ngừng tiêu. Bạn có thể nhắn tin cho bạn bè, và tin nhắn riêng được mã hóa đầu cuối. Bảng nói khoảng 120 ngôn ngữ, gồm tiếng Hà Lan, Flemish, cướp biển và Klingon. Không thứ nào tốn một xu, và cũng chẳng ai đang cố bán gì cho bạn.","AI-gile là một dự án nhỏ, cá nhân, không phải một công ty. Rich muốn trông nom vài dự án lập trình AI mà không phải mở từng ứng dụng ra xem, nên anh và các agent làm một chiếc bảng cho việc đó, rồi dùng chính chiếc bảng ấy để làm nốt phần còn lại. Nó đang ở giai đoạn tiền alpha kín, nghĩa là phần lớn chạy được, cho một nhúm bạn bè. Không có trang bảng giá, không bản tin, không kế hoạch tăng trưởng. Nếu nghe hữu ích, bạn có thể xin thử khi nó mở rộng hơn một chút."]},{"n":144,"texts":["AI-gile là một bảng kanban cho một con người và rất nhiều agent AI. Nó chạy trên máy tính của bạn và hoàn toàn miễn phí. Bạn thêm các dự án, và mỗi dự án có một trưởng nhóm cùng một nhóm nhỏ. Bạn trò chuyện với trưởng nhóm, hơi giống Discord, và mô tả một ý tưởng; trưởng nhóm biến nó thành thẻ và kế hoạch, rồi chờ bạn bấm Bắt đầu. Cả nhóm làm lần lượt các thẻ theo thứ tự ưu tiên, bằng một dòng lệnh đơn giản làm riêng cho các mô hình ngôn ngữ. Trước khi bất cứ thứ gì quay lại với bạn, một người kiểm thử AI làm theo các bước trong một bản sao của ứng dụng và đính kèm ảnh chụp màn hình. Việc xong rơi vào chồng của bạn cùng các tệp đã đổi và phần khác biệt. Bạn chấp nhận, hoặc để lại bình luận và cả nhóm thức dậy làm lại. Chỉ bạn mới chuyển được thẻ sang Xong.","Một ngày với AI-gile, đại khái thế này. Buổi tối bạn để lại vài bình luận: nút này sai chỗ, danh sách kia nên được sắp xếp, có thể thêm chế độ tối không. Bạn đi ngủ. Các agent đọc bình luận, sửa, kiểm thử rồi giao lại cho bạn. Nếu cột Cần làm cạn, người gác đêm sẽ lấy từ backlog những thẻ không cần bạn trả lời để lấp đầy. Sáng ra chỉ có một chồng ngắn: vài câu hỏi và vài thứ để thử, mỗi cái kèm các bước mà người còn ngái ngủ cũng làm theo được và một ảnh chụp màn hình cho thấy nó chạy. Bạn bấm qua, chấp nhận cái tốt và gửi trả phần còn lại. Bộ đếm token cho thấy tất cả tốn bao nhiêu, và Chế độ Không Token dành cho những tuần phải tiết kiệm. Rồi bạn ăn sáng, việc mà các agent chưa giúp được.","Trước hết, AI-gile không phải là gì. Nó không phải công ty khởi nghiệp, không bán, và không ai thu thập dữ liệu của bạn. Nó là một bảng miễn phí chạy trên máy bạn, không tài khoản, không trình theo dõi, không cookie. Còn nó là gì: một nơi gọn gàng để thấy mọi dự án lập trình AI cùng lúc, với một nhóm agent làm thẻ và bạn là người quyết định. Nó gộp các thẻ liên quan, sửa tiêu đề rối, và để mắt xem mã còn gọn đến đâu. Nó nói khoảng 120 ngôn ngữ, từ tiếng Hà Lan và Flemish đến cướp biển và Klingon. Bạn bè có thể nhắn nhau, riêng tư và được mã hóa. Nó do Rich và rất nhiều agent kiên nhẫn làm ra, phần lớn bằng cách tự dùng chính nó. Nó đang ở giai đoạn tiền alpha kín, nên có chỗ còn thô. Nếu nghe vui, hãy hỏi lịch sự, biết đâu bạn vào sớm."]}],"quips":{"1":"Một từ. Táo bạo. Có lẽ hơi quá táo bạo.","3":"Ba từ. Đã thật thà hơn đa số trang sản phẩm.","8":"Tám từ. Vẫn ngắn hơn một buổi họp đứng.","21":"Nhân tiện, các độ dài là story point. Dĩ nhiên rồi.","55":"Năm mươi lăm từ. Trong lúc bạn đọc, hai thẻ đã xong.","144":"Đó là bản dài nhất. Không có 233. Các agent đi ngủ rồi."}},"timeline":{"first-idea.name":"Ý tưởng đầu tiên","first-idea.line":"Cuộc trò chuyện đầu tiên, khi chưa có dòng mã nào.","first-board.name":"Bảng đầu tiên","first-board.line":"Một bảng theo dõi chính quá trình xây nó: thẻ, cột, kéo thả, dự án.","team-roles.name":"Nhóm và vai trò","team-roles.line":"Hồ sơ agent, mẫu nhóm, không gian và ai làm gì.","install.name":"Cài đặt và phát hành","install.line":"Một tệp zip bạn bè cài được, tự cập nhật, các kênh và quay lui.","usage-saver.name":"Tiết kiệm lượt dùng","usage-saver.line":"Đo chi phí mỗi lần chạy, giữ mã gọn nhẹ, giữ hạn mức của bạn.","friends.name":"Bạn bè và chia sẻ","friends.line":"Tin nhắn riêng, máy chuyển tiếp đã xáo trộn, lời mời, vai trò và dự án chung.","languages.name":"Ngôn ngữ","languages.line":"Mọi chữ trên màn hình nằm trong một tệp ngôn ngữ, tiếng Hà Lan và tiếng Flemish trước.","ai-tester.name":"Người kiểm thử AI","ai-tester.line":"Một người kiểm thử xem mọi lần bàn giao trước và cho xem điều đã thấy.","website.name":"Trang web","website.line":"aigile.lol, trang giới thiệu và dòng thời gian này.","streaming.name":"Trò chuyện và phát trực tiếp","streaming.line":"Discord, Twitch, OBS, chế độ streamer, GIF và emoji.","no-ai.name":"Bản không AI","no-ai.line":"Một bảng cho người lập trình không dùng AI, và các bảng công khai.","night-watch.name":"Gác đêm","night-watch.line":"Một người gác và Scrum Master giữ các nhóm đúng việc khi bạn ngủ.","p-more.name":"Mọi thứ còn lại","p-more.line":"Những ý tưởng nhỏ hơn vẫn đang chờ đến lượt.","p-android.name":"Điện thoại và Android","p-android.line":"Vào bảng của bạn từ điện thoại, rồi một ứng dụng Android riêng.","p-release.name":"Alpha và xa hơn","p-release.line":"Alpha kín, trang web chính thức, rồi beta.","p-languages.name":"Thêm ngôn ngữ","p-languages.line":"130 ngôn ngữ, cùng chế độ luyện ngôn ngữ cho người học.","p-engines.name":"Thêm công cụ AI","p-engines.line":"Chọn Claude, Codex, Gemini, Copilot hoặc Cursor cho từng agent.","p-pro.name":"Thực hành chuyên nghiệp","p-pro.line":"Nhãn rủi ro, cổng hợp nhất, thẻ sự cố và rào chắn an toàn.","p-self.name":"Chăm sóc bạn","p-self.line":"Chế độ mệt mỏi, nhắc nhở chăm sóc bản thân và 4:20.","p-servers.name":"Máy chủ và quy mô","p-servers.line":"Cài đặt máy chủ toàn cục, vai trò và kế hoạch để phát triển.","p-livestream.name":"Tiện ích phát trực tiếp","p-livestream.line":"Trò chuyện Twitch, emoji tùy chỉnh và chế độ xem trực tiếp công khai."},"words":{"button":"📖 Thuật ngữ chuyên ngành","h":"📖 Giải thích từ ngữ","intro":"Đào tạo miễn phí bằng lời dễ hiểu: mọi từ bạn sẽ gặp trên đường từ ý tưởng đầu tiên đến một dịch vụ mà mọi người tin dùng, gồm cả Agile, cách xây dựng, giữ an toàn và làm việc với AI.","search":"Tìm một từ…","none":"Không có từ nào khớp.","close":"Đóng","count":{"one":"{count} từ","other":"{count} từ"},"groups":[{"id":"idea","name":"💡 Ý tưởng và khám phá"},{"id":"plan","name":"🗺️ Lập kế hoạch công việc"},{"id":"agile","name":"🔁 Cách làm việc Agile"},{"id":"build","name":"🛠️ Làm ra sản phẩm"},{"id":"test","name":"🧪 Kiểm thử và chất lượng"},{"id":"change","name":"🔀 Thay đổi an toàn"},{"id":"run","name":"🛎️ Vận hành dịch vụ"},{"id":"sec","name":"🔒 Bảo mật và riêng tư"},{"id":"ai","name":"🤖 Làm việc với AI"},{"id":"money","name":"💰 Tiền bạc và giấy phép"}],"list":[{"id":"discovery","g":"idea","word":"Khám phá","text":"Giai đoạn đầu để tìm ra vấn đề nào đáng giải quyết và giải quyết cho ai, trước khi bắt tay xây dựng bất cứ thứ gì.","also":["giai đoạn khám phá","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Phát biểu vấn đề","text":"Một hai câu nói rõ ai đang gặp vấn đề, vấn đề đó là gì và vì sao nó quan trọng, để mọi người cùng nhắm vào một mục tiêu.","also":["problem statements"]},{"id":"user","g":"idea","word":"Người dùng","text":"Người sử dụng thứ bạn làm ra. Công việc là để phục vụ nhu cầu của họ.","also":["người dùng","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Bên liên quan","text":"Bất kỳ ai quan tâm đến kết quả công việc hoặc chịu ảnh hưởng của nó, như người trả tiền, người dùng hay người hỗ trợ.","also":["các bên liên quan","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Một nhân vật hư cấu nhưng giống người thật, đại diện cho một kiểu người dùng, để nhóm có thể tự hỏi “bạn Sam có thấy cái này dễ dùng không?”","also":["chân dung người dùng","personas"]},{"id":"userresearch","g":"idea","word":"Nghiên cứu người dùng","text":"Trò chuyện và quan sát những người thật để biết họ cần gì, thay vì đoán.","also":["phỏng vấn người dùng","user interviews"]},{"id":"journey","g":"idea","word":"Hành trình người dùng","text":"Các bước một người trải qua để hoàn thành một việc, từ lúc nghe nói đến lúc xong, kể cả những bước ngoài sản phẩm của bạn. Vẽ ra sẽ thấy họ bị kẹt ở đâu.","also":["hành trình khách hàng","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Điểm gây khó chịu","text":"Điều đang làm người ta bực mình hoặc chậm lại hiện nay. Sản phẩm tốt sẽ xóa bỏ những điểm này.","also":["pain points","nỗi đau của người dùng"]},{"id":"assumption","g":"idea","word":"Giả định","text":"Điều bạn tin là đúng nhưng chưa kiểm tra. Viết các giả định ra sẽ cho thấy nên kiểm tra điều gì trước.","also":["giả định","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Giả thuyết","text":"Một dự đoán tốt nhất mà bạn định kiểm chứng, kèm điều bạn mong đợi, như “mọi người sẽ đăng ký nếu tháng đầu miễn phí”.","also":["giả thuyết","hypotheses"]},{"id":"experiment","g":"idea","word":"Thử nghiệm","text":"Một bài thử nhỏ có kế hoạch để biết một ý tưởng có hiệu quả không, trước khi đặt cược nhiều vào nó.","also":["thí nghiệm","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Thử nghiệm khả thi (PoC)","text":"Một lần thử nhanh, sơ sài để xem ý tưởng có làm được không. Có câu trả lời xong thường là bỏ đi.","also":["PoC","proof of concept","bản chứng minh khái niệm"]},{"id":"prototype","g":"idea","word":"Bản mẫu","text":"Một mô hình ban đầu của sản phẩm, thường là các hình ảnh bấm được, để thử ý tưởng với mọi người trước khi làm cho đàng hoàng.","also":["prototypes","nguyên mẫu"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Bản phác thảo đơn giản của một màn hình, cho thấy mọi thứ nằm ở đâu, chưa có màu sắc hay nội dung thật.","also":["wireframes","khung sườn giao diện"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Bức hình chi tiết cho thấy màn hình sẽ trông thế nào, với màu sắc và chữ thật, nhưng chưa có gì hoạt động.","also":["mockups","mock-up","mock-ups","bản thiết kế giao diện"]},{"id":"bizcase","g":"idea","word":"Phân tích hiệu quả kinh doanh","text":"Những lý do để làm một dự án: tốn bao nhiêu, mang lại hay tiết kiệm được bao nhiêu, và các rủi ro.","also":["business cases","luận chứng kinh doanh"]},{"id":"feasibility","g":"idea","word":"Tính khả thi","text":"Việc có thể thật sự xây dựng và duy trì một thứ với thời gian, tiền bạc và kỹ năng bạn đang có hay không.","also":["khả thi"]},{"id":"outcome","g":"idea","word":"Kết quả mong muốn","text":"Sự thay đổi bạn muốn mang lại cho mọi người, như ít người lỡ hẹn hơn. Nó quan trọng hơn việc bạn làm ra được bao nhiêu thứ.","also":["outcomes","thành quả"],"noTip":1},{"id":"output","g":"idea","word":"Sản phẩm đầu ra","text":"Thứ mà nhóm làm ra, như một màn hình mới hay một bản báo cáo. Làm ra nó chưa chắc đã giúp được ai.","also":["outputs","đầu ra"],"noTip":1},{"id":"successmetric","g":"idea","word":"Chỉ số thành công","text":"Một con số cho biết công việc có đạt mục đích hay không, như nhiều người hoàn tất đơn hàng hơn.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Chỉ số hiệu suất chính (KPI)","text":"Một con số quan trọng bạn theo dõi để biết mọi thứ có đang tốt không, như số người đăng ký mỗi tuần.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Mục tiêu và kết quả then chốt (OKR)","text":"Một cách đặt mục tiêu: mục tiêu nói bạn muốn gì, còn vài kết quả then chốt là những con số cho thấy bạn đã đạt được.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Sản phẩm","text":"Thứ được xây dựng và chăm sóc cho người dùng của nó, như một ứng dụng, một trang web hay một công cụ.","also":["sản phẩm","products"],"noTip":1},{"id":"vision","g":"plan","word":"Tầm nhìn sản phẩm","text":"Một câu ngắn nói sản phẩm giúp ai và về lâu dài sẽ đi về đâu.","also":["vision statement","tuyên bố tầm nhìn"]},{"id":"po","g":"plan","word":"Chủ sản phẩm (PO)","text":"Người quyết định cái gì được làm và theo thứ tự nào, để nhóm luôn làm việc quan trọng nhất. Trong AI-gile, đó là bạn.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Quản lý sản phẩm (PM)","text":"Người chăm lo hướng đi của một sản phẩm: giải quyết vấn đề gì, cho ai và vì sao. PM cũng có thể là quản lý dự án, nên hãy xem là nghĩa nào.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Quản lý dự án","text":"Người giữ cho dự án đúng hạn và đúng ngân sách, theo dõi ai làm gì và đến khi nào.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Lộ trình","text":"Kế hoạch sơ lược về những gì sẽ đến trong vài tháng tới, theo thứ tự. Nó cho thấy hướng đi chứ không phải ngày chính xác, và thay đổi theo những gì bạn học được.","also":["roadmaps","lộ trình sản phẩm"]},{"id":"milestone","g":"plan","word":"Cột mốc","text":"Một điểm trong dự án đáng đánh dấu, như “phiên bản đầu tiên ra mắt” hay “đạt 100 người dùng”.","also":["milestones","mốc quan trọng"]},{"id":"mvp","g":"plan","word":"Sản phẩm khả dụng tối thiểu (MVP)","text":"Phiên bản nhỏ nhất của sản phẩm mà vẫn hữu ích cho người thật, để bạn học hỏi từ họ sớm.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Yêu cầu","text":"Điều sản phẩm hoàn chỉnh phải làm được hoặc phải có.","also":["requirements","yêu cầu sản phẩm"],"noTip":1},{"id":"scope","g":"plan","word":"Phạm vi","text":"Những gì nằm trong công việc và, cũng quan trọng không kém, những gì không nằm trong đó.","also":["trong phạm vi","ngoài phạm vi","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Phình phạm vi","text":"Khi công việc bị thêm dần từng chút một mà không ai thống nhất về thời gian hay chi phí tăng thêm, nên không bao giờ thật sự xong.","also":["scope creep","feature creep","phình to tính năng"]},{"id":"feature","g":"plan","word":"Tính năng","text":"Một điều sản phẩm làm được cho mọi người, như “đặt lại mật khẩu”.","also":["features","chức năng"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Một khối việc lớn, quá to để làm một lần, nên được chia thành các thẻ nhỏ hơn.","also":["epics","đầu việc lớn"]},{"id":"story","g":"plan","word":"User story","text":"Một đầu việc nhỏ được viết từ phía người dùng: “Là người mua hàng, tôi muốn lưu giỏ hàng để có thể hoàn tất sau.” Nó mở ra cuộc trò chuyện về việc cần làm.","also":["user stories","câu chuyện người dùng"]},{"id":"ac","g":"plan","word":"Tiêu chí chấp nhận (AC)","text":"Những điều kiện một thẻ phải đạt để được coi là xong, thống nhất trước khi bắt đầu, như “giỏ hàng vẫn còn sau khi tôi đăng xuất rồi đăng nhập lại”.","also":["acceptance criteria","tiêu chí nghiệm thu"]},{"id":"task","g":"plan","word":"Nhiệm vụ","text":"Một việc đơn lẻ cần làm, thường là một bước nhỏ của một câu chuyện lớn hơn.","also":["tasks","tác vụ"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Một cách gọi khác của thẻ: một đầu việc hoặc một yêu cầu, được theo dõi từ đầu đến cuối.","also":["tickets","phiếu việc"]},{"id":"priority","g":"plan","word":"Mức ưu tiên","text":"Mức độ quan trọng hoặc khẩn cấp của một việc so với mọi thứ khác, để việc quan trọng nhất được làm trước.","also":["ưu tiên","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Sắp xếp ưu tiên","text":"Xếp công việc theo thứ tự quan trọng. Một cách phổ biến là MoSCoW: Must have (phải có), Should have (nên có), Could have (có thì tốt), Won’t have (lần này không làm).","also":["xếp thứ tự ưu tiên","MoSCoW"]},{"id":"estimate","g":"plan","word":"Ước lượng","text":"Phỏng đoán tốt nhất về một việc lớn cỡ nào hoặc mất bao lâu. Đó là phỏng đoán, không phải lời hứa.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"Cách đoán độ lớn của công việc bằng cách so các thẻ với nhau (“to gấp đôi cái kia”) thay vì tính bằng giờ. Không dùng để so sánh các nhóm.","also":["story point","điểm story"]},{"id":"tshirt","g":"plan","word":"Ước lượng theo cỡ áo","text":"Đoán độ lớn của công việc là S, M, L hoặc XL. Nhanh và đủ tốt cho giai đoạn lập kế hoạch ban đầu.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Một trò chơi để ước lượng: mọi người cùng lúc lật lá bài ghi cỡ việc, rồi người chọn cao nhất và thấp nhất giải thích lý do.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Phụ thuộc","text":"Khi một việc không thể bắt đầu hoặc kết thúc cho đến khi một việc khác xong.","also":["dependencies","sự phụ thuộc"]},{"id":"blocker","g":"plan","word":"Vật cản","text":"Bất cứ thứ gì đang chặn công việc tiến lên lúc này, như một câu trả lời còn thiếu hay một công cụ bị hỏng.","also":["blockers","điểm nghẽn"]},{"id":"deadline","g":"plan","word":"Hạn chót","text":"Ngày mà một việc phải hoàn thành.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Sản phẩm bàn giao","text":"Thứ cụ thể mà công việc làm ra và bàn giao, như một trang chạy được hoặc một bản báo cáo.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Dự báo","text":"Dự đoán điều có khả năng xảy ra, như khi nào công việc xong, dựa trên những gì bạn biết cho đến giờ.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Chỉ số","text":"Bất cứ thứ gì bạn đo và theo dõi theo thời gian, như lượt truy cập trang hay thời gian sửa một lỗi.","also":["metrics","số đo"]},{"id":"feedback","g":"plan","word":"Phản hồi","text":"Những gì mọi người nói với bạn về công việc của bạn, cả tốt lẫn xấu. Nhận phản hồi sớm và thường xuyên là cốt lõi của Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Danh sách chờ các ý tưởng và công việc chưa được xếp vào kế hoạch, việc quan trọng nhất ở trên cùng. Không việc nào trong đó được làm cho đến khi chuyển sang Cần làm."},{"id":"sprint","g":"agile","word":"Sprint","text":"Một quãng làm việc ngắn, cố định (thường một hai tuần, không bao giờ quá một tháng) với một mục tiêu và một số thẻ đã thống nhất cần hoàn thành.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Buổi cập nhật nhanh hằng ngày: mỗi thành viên đã làm gì, sắp làm gì và điều gì đang cản trở. Trong Scrum gọi là daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","họp đứng","họp nhanh hằng ngày"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Cách làm việc mà các thẻ di chuyển qua các cột của một cái bảng (như Cần làm, Đang làm, Xong) và nhóm giới hạn số việc đang làm cùng lúc, để công việc luôn trôi chảy."},{"id":"wip","g":"agile","word":"Giới hạn WIP","text":"WIP là viết tắt của work in progress (việc đang làm dở). Giới hạn WIP là số thẻ tối đa một cột nên chứa cùng lúc, để nhóm làm xong việc trước khi bắt đầu thêm.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Danh sách ngắn của nhóm về thế nào là “xong”, như đã test và đã giải thích, trước khi thẻ được giao cho bạn. Người anh em sinh đôi của nó, Definition of Ready, cho biết khi nào một thẻ đủ rõ để bắt đầu.","also":["Definition of Ready","DoD","DoR","định nghĩa hoàn thành"]},{"id":"retro","g":"agile","word":"Retro","text":"Cùng nhìn lại đều đặn cách nhóm làm việc, để thống nhất một hai điều làm tốt hơn lần sau. Viết tắt của retrospective. Trong AI-gile, một buổi retro đề xuất một thay đổi cho cách làm việc của nhóm, và bạn chọn Go hoặc Chưa đâu.","also":["retros","retrospective","retrospectives","họp nhìn lại"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Tất cả cùng xông vào: nhiều người bỏ việc khác để cùng sửa một việc gấp cho đến khi xong. Trong AI-gile, mọi nhóm cùng giúp một dự án, còn các dự án khác tạm chờ.","also":["swarming","dồn lực"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Trong Scrum, người giúp nhóm làm việc tốt: gỡ những thứ cản trở, giữ các cuộc họp đi đúng hướng và huấn luyện thói quen tốt, mà không sai khiến ai. Trong AI-gile, Lead Scrum Master phát hiện các thẻ bị kẹt, nhắc các nhóm và nhắc bạn những gì đang chờ, ở mọi dự án.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Cách làm việc theo từng bước nhỏ: làm một chút, thường xuyên cho xem kết quả thật, học từ ý kiến của mọi người và đổi kế hoạch khi cần, thay vì lên kế hoạch hết từ đầu.","also":["Agile development","agile ways of working","phát triển linh hoạt"]},{"id":"manifesto","g":"agile","word":"Tuyên ngôn Agile","text":"Một bản tuyên bố ngắn do những người làm phần mềm viết năm 2001. Nó đặt con người, kết quả chạy được, sự hợp tác sát với khách hàng và khả năng thích ứng với thay đổi lên trên các kế hoạch nặng nề và giấy tờ.","also":["Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Thác nước (Waterfall)","text":"Cách làm việc cũ: lên kế hoạch hết, rồi xây dựng hết, rồi kiểm thử hết, hết giai đoạn này đến giai đoạn khác. Đổi ý ở giai đoạn muộn rất khó và tốn kém.","also":["waterfall model","mô hình thác nước"]},{"id":"iteration","g":"agile","word":"Vòng lặp","text":"Một vòng làm ra một thứ, kiểm tra và cải thiện nó. Công việc Agile là một chuỗi các vòng như vậy, và sprint là một dạng.","also":["iterations","lần lặp"]},{"id":"increment","g":"agile","word":"Phần tăng thêm","text":"Một phần mới chạy được thêm vào sản phẩm trong một sprint hoặc một vòng làm việc, khớp với những gì đã có.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Một cách làm việc Agile phổ biến: một nhóm nhỏ làm việc theo các sprint ngắn hướng tới một mục tiêu, với các vai trò cố định và vài cuộc họp đều đặn để lập kế hoạch, kiểm tra và cải tiến."},{"id":"scrumteam","g":"agile","word":"Nhóm Scrum","text":"Nhóm nhỏ làm việc trong Scrum: một chủ sản phẩm, một Scrum Master và các lập trình viên.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Các sự kiện Scrum","text":"Các cuộc họp đều đặn trong Scrum: lập kế hoạch sprint, họp Scrum hằng ngày, sơ kết sprint và họp cải tiến. Nhiều người gọi chúng là các “nghi thức”.","also":["ceremonies","Scrum ceremonies","nghi thức Scrum"]},{"id":"sprintplan","g":"agile","word":"Lập kế hoạch sprint","text":"Cuộc họp đầu sprint, nơi nhóm thống nhất vì sao sprint này quan trọng, nhận những thẻ nào và bắt đầu thế nào.","also":["planning meeting","họp lập kế hoạch"]},{"id":"sprintgoal","g":"agile","word":"Mục tiêu sprint","text":"Một câu nói sprint này để làm gì. Các việc nhỏ có thể đổi trên đường đi, miễn là đạt được mục tiêu.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Backlog của sprint","text":"Các thẻ được chọn cho sprint hiện tại, cùng kế hoạch thực hiện của nhóm.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Backlog sản phẩm","text":"Danh sách đầy đủ, có thứ tự, của mọi thứ có thể được làm cho sản phẩm, việc quan trọng nhất ở trên cùng. Danh sách này liên tục thay đổi khi bạn học thêm.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Mục tiêu sản phẩm","text":"Kết quả lớn hơn mà sản phẩm đang hướng tới, giúp nhóm chọn việc tiếp theo.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Tinh chỉnh backlog","text":"Thường xuyên xem lại backlog để dọn dẹp, chia nhỏ, sắp xếp và bổ sung chi tiết cho các thẻ, để sẵn sàng nhận việc. Còn gọi là backlog grooming.","also":["backlog grooming","refinement","chải chuốt backlog"]},{"id":"sprintreview","g":"agile","word":"Sơ kết sprint","text":"Cuộc họp cuối sprint, nơi nhóm cho xem những gì đã xong và nghe mọi người nghĩ gì, để quyết định bước tiếp theo.","also":["sprint reviews","họp review sprint"]},{"id":"demo","g":"agile","word":"Demo","text":"Cho những người đã yêu cầu được xem trực tiếp phần việc đã xong đang chạy thật.","also":["demos","trình diễn"],"noTip":1},{"id":"timebox","g":"agile","word":"Khung thời gian cố định","text":"Một khoảng thời gian cố định cho một việc. Hết giờ là dừng, dù chưa xong hết.","also":["timeboxed","timeboxes","timebox"]},{"id":"velocity","g":"agile","word":"Tốc độ làm việc (Velocity)","text":"Lượng việc một nhóm thường làm xong trong một sprint, dùng để tính lần sau nên nhận bao nhiêu. Đây không phải điểm số đo mức độ chăm chỉ của mọi người.","also":["team velocity","velocity"]},{"id":"capacity","g":"agile","word":"Năng lực làm việc","text":"Lượng việc nhóm có thể nhận trong một khoảng thời gian, sau khi trừ ngày nghỉ và các việc khác.","noTip":1},{"id":"burndown","g":"agile","word":"Biểu đồ burndown","text":"Biểu đồ cho thấy lượng việc còn lại trong sprint giảm dần từng ngày. Nếu đường cứ nằm ngang thì có chỗ nào đó đang bị kẹt.","also":["burndown","burn-down chart","biểu đồ giảm dần"]},{"id":"burnup","g":"agile","word":"Biểu đồ burnup","text":"Biểu đồ cho thấy việc đã xong tăng dần theo thời gian, bên cạnh tổng số việc dự kiến, để bạn thấy khi nào sẽ đến đích.","also":["burnup","burn-up chart","biểu đồ tăng dần"]},{"id":"kanbanboard","g":"agile","word":"Bảng Kanban","text":"Chính là cái bảng này: mỗi giai đoạn của công việc là một cột, và các thẻ di chuyển qua các cột.","also":["Kanban boards","Kanban board"]},{"id":"pullsys","g":"agile","word":"Hệ thống kéo (pull)","text":"Cách làm việc mà việc mới chỉ bắt đầu khi có người còn chỗ để nhận, thay vì bị dồn thêm vào một đĩa đã đầy.","also":["pull-based","pull system"]},{"id":"flow","g":"agile","word":"Dòng chảy công việc","text":"Công việc di chuyển qua bảng trôi chảy đến đâu. Dòng chảy tốt nghĩa là các thẻ cứ tiến lên chứ không chất đống.","also":["flow of work","flow"],"noTip":1},{"id":"leadtime","g":"agile","word":"Thời gian đáp ứng (lead time)","text":"Thời gian từ lúc có người yêu cầu một việc đến lúc việc đó xong.","also":["lead times","lead time"]},{"id":"cycletime","g":"agile","word":"Thời gian xử lý (cycle time)","text":"Thời gian một thẻ mất đi từ lúc thật sự bắt tay làm đến lúc xong.","also":["cycle times","cycle time"]},{"id":"throughput","g":"agile","word":"Thông lượng","text":"Số thẻ hoàn thành trong một tuần, hoặc trong bất kỳ khoảng thời gian nhất định nào.","also":["throughput rate","throughput"]},{"id":"bottleneck","g":"agile","word":"Nút thắt cổ chai","text":"Giai đoạn mà công việc dồn ứ lại và làm chậm mọi thứ phía sau, giống như cổ chai hẹp.","also":["bottlenecks","bottleneck","điểm nghẽn"]},{"id":"swimlane","g":"agile","word":"Làn bơi (swimlane)","text":"Một hàng ngang trên bảng gom các thẻ cùng loại, như việc gấp hoặc các thẻ của một nhóm.","also":["swimlanes","swim lane","swimlane"]},{"id":"lean","g":"agile","word":"Lean","text":"Cách làm việc cắt bỏ lãng phí (mọi thứ không giúp ích cho khách hàng) và giữ cho công việc trôi chảy."},{"id":"waste","g":"agile","word":"Lãng phí","text":"Trong Lean, là mọi thứ tốn công sức mà không giúp ích cho khách hàng, như chờ đợi, làm lại hay xây thứ không ai dùng.","noTip":1},{"id":"kaizen","g":"agile","word":"Cải tiến liên tục","text":"Tốt lên một chút mỗi ngày nhờ những thay đổi nhỏ đều đặn, rồi kiểm tra xem chúng có giúp ích không. Họp retro là một cách làm. Còn gọi là kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Nhóm tự tổ chức","text":"Nhóm tự quyết định cách làm việc, thay vì bị chỉ từng bước một.","also":["self-organising","self-managing team","nhóm tự quản"]},{"id":"crossfunc","g":"agile","word":"Nhóm đa chức năng","text":"Nhóm có đủ mọi kỹ năng cần thiết để tự hoàn thành công việc, như thiết kế, xây dựng và kiểm thử.","also":["cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike","text":"Một đợt nghiên cứu ngắn, có giới hạn thời gian để trả lời một câu hỏi trước khi cam kết làm việc thật.","also":["spikes","nghiên cứu nhanh"]},{"id":"rework","g":"agile","word":"Làm lại","text":"Làm lại một việc vì lần đầu làm chưa đúng.","also":["reworked","rework"]},{"id":"safe","g":"agile","word":"Agile quy mô lớn (SAFe)","text":"Các cách áp dụng Agile cho nhiều nhóm trong một tổ chức lớn. SAFe (Scaled Agile Framework) là một ví dụ nổi tiếng.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Thư mục code của dự án cùng toàn bộ lịch sử commit. Nó có thể nằm trên máy tính của bạn, trên GitHub, hoặc cả hai.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Một nhánh làm việc riêng trong code, để có thể thay đổi mà không đụng đến bản chính.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Một bản chụp đã lưu của code, kèm ghi chú ngắn về điều đã đổi. Bạn luôn có thể quay lại một bản.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Gửi các bản lưu (commit) của bạn từ máy tính này lên bản dùng chung trên mạng, như GitHub, để chúng được sao lưu và người khác lấy về được."},{"id":"merge","g":"build","word":"Merge","text":"Gộp các thay đổi từ một nhánh vào nhánh khác, thường là vào lại bản chính."},{"id":"pr","g":"build","word":"Pull request","text":"Đề nghị kiểm tra các thay đổi của một nhánh và gộp chúng vào bản chính. Một số trang gọi là merge request.","also":["PR","PRs","merge request","yêu cầu gộp"]},{"id":"refactor","g":"build","word":"Refactor","text":"Dọn dẹp code mà không đổi việc nó làm: tệp nhỏ hơn, tên rõ hơn, bớt lặp lại."},{"id":"bug","g":"build","word":"Bug","text":"Chỗ nào đó không hoạt động đúng như lẽ ra phải thế.","also":["bugs","lỗi"]},{"id":"peerreview","g":"build","word":"Đánh giá ngang hàng","text":"Thêm một đôi mắt thứ hai: người khác ngoài tác giả kiểm tra công việc trước khi đến tay bạn, để ít lỗi lọt qua hơn. Trong AI-gile, một AI khác kiểm tra từng thẻ.","also":["review code","peer review","code review"]},{"id":"code","g":"build","word":"Mã (code)","text":"Những chỉ dẫn bằng chữ bảo máy tính phải làm gì. Còn gọi là mã nguồn.","also":["source code","mã nguồn","code"],"noTip":1},{"id":"proglang","g":"build","word":"Ngôn ngữ lập trình","text":"Ngôn ngữ dùng để viết code, như JavaScript, Python hay Java. Mỗi ngôn ngữ hợp với một loại việc khác nhau.","also":["programming languages","programming language"]},{"id":"developer","g":"build","word":"Lập trình viên (dev)","text":"Người viết và sửa code. Còn gọi là programmer hay kỹ sư phần mềm.","also":["developer","developers","programmer","programmers","software engineer","kỹ sư phần mềm"]},{"id":"software","g":"build","word":"Phần mềm","text":"Các chương trình chạy trên máy tính và điện thoại, khác với bản thân máy móc (phần cứng).","noTip":1},{"id":"app","g":"build","word":"Ứng dụng (app)","text":"Viết tắt của application: chương trình mọi người dùng để làm một việc gì đó, trên điện thoại, máy tính hoặc trong trình duyệt web.","also":["apps","application","applications","ứng dụng"],"noTip":1},{"id":"webapp","g":"build","word":"Ứng dụng web","text":"Ứng dụng chạy trong trình duyệt web, nên không cần cài đặt gì.","also":["web apps","web application","web app"]},{"id":"frontend","g":"build","word":"Front end (giao diện)","text":"Phần của ứng dụng bạn nhìn thấy và bấm vào: màn hình, nút bấm và chữ, thường nằm trong trình duyệt của bạn.","also":["front-end","frontend","phần giao diện"]},{"id":"backend","g":"build","word":"Back end (phần xử lý phía sau)","text":"Phần hoạt động ngầm của ứng dụng, giữ dữ liệu và làm việc khi bạn bấm vào đâu đó, như kiểm tra mật khẩu của bạn.","also":["back-end","backend","phần phía sau"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Làm việc cả ở front end lẫn back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"Giao diện người dùng (UI)","text":"Những gì một người nhìn thấy và dùng trên màn hình: bố cục, nút bấm, menu và chữ.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Trải nghiệm người dùng (UX)","text":"Cảm giác khi dùng một thứ: dễ, rõ ràng và dễ chịu, hay rối rắm và chậm chạp.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Khả năng tiếp cận (a11y)","text":"Làm cho mọi người đều dùng được, kể cả những người nhìn kém, không dùng được chuột hoặc dùng trình đọc màn hình.","also":["a11y","accessibility","trợ năng"]},{"id":"responsive","g":"build","word":"Thiết kế đáp ứng (responsive)","text":"Làm cho trang vừa vặn và dùng tốt trên mọi cỡ màn hình, từ điện thoại đến màn hình lớn.","also":["responsive design"]},{"id":"designsys","g":"build","word":"Hệ thống thiết kế","text":"Bộ dùng chung gồm màu sắc, phông chữ, nút bấm và quy tắc, để mọi màn hình trông và hoạt động giống nhau.","also":["design systems","design system"]},{"id":"architecture","g":"build","word":"Kiến trúc","text":"Hình dạng tổng thể của một hệ thống: các phần chính là gì và chúng nói chuyện với nhau thế nào."},{"id":"database","g":"build","word":"Cơ sở dữ liệu (DB)","text":"Nơi lưu thông tin có tổ chức, giống như một bảng tính cực mạnh mà ứng dụng có thể đọc và sửa.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Lược đồ cơ sở dữ liệu","text":"Cách bố trí của cơ sở dữ liệu: có những bảng thông tin nào và mỗi bảng chứa gì.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Viết tắt của structured query language (ngôn ngữ truy vấn có cấu trúc): ngôn ngữ dùng để hỏi thông tin hoặc sửa thông tin trong nhiều cơ sở dữ liệu.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Dữ liệu","text":"Thông tin được máy tính lưu giữ, như tên, đơn hàng hay các cài đặt.","also":["dataset","datasets","data"],"noTip":1},{"id":"server","g":"build","word":"Máy chủ","text":"Máy tính luôn bật và trả lời yêu cầu từ các máy tính khác, như gửi một trang web khi bạn truy cập.","also":["servers","server"]},{"id":"client","g":"build","word":"Máy khách (client)","text":"Phía đưa ra yêu cầu, thường là trình duyệt hoặc ứng dụng của bạn, nói chuyện với máy chủ. Trong kinh doanh, từ này còn đơn giản là khách hàng.","also":["clients","client"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Viết tắt của application programming interface: một thực đơn các yêu cầu mà chương trình này có thể gửi cho chương trình khác, như hỏi dịch vụ thời tiết dự báo hôm nay.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Một món trong thực đơn của API: một địa chỉ web mà chương trình có thể gọi để lấy hoặc gửi thứ gì đó.","also":["endpoints","điểm cuối"]},{"id":"integration","g":"build","word":"Tích hợp","text":"Kết nối hai hệ thống để chúng làm việc cùng nhau, như cửa hàng của bạn gửi đơn hàng sang phần mềm kế toán.","also":["integrations","integration"]},{"id":"webhook","g":"build","word":"Webhook","text":"Tin nhắn mà một hệ thống tự gửi cho hệ thống khác ngay khi có chuyện xảy ra, như “đã nhận tiền”.","also":["webhooks"]},{"id":"library","g":"build","word":"Thư viện (library)","text":"Code viết sẵn của người khác mà bạn có thể dùng lại thay vì tự viết.","also":["libraries","library"],"noTip":1},{"id":"framework","g":"build","word":"Framework (khung sườn)","text":"Cấu trúc làm sẵn để xây một ứng dụng, quyết định phần lớn cách sắp xếp code, như khung nhà mà bạn lấp đầy.","also":["frameworks","framework","khung phát triển"]},{"id":"sdk","g":"build","word":"Bộ công cụ phát triển phần mềm (SDK)","text":"Một hộp gồm công cụ, code và ví dụ để xây phần mềm cho một nền tảng hoặc dịch vụ.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Thư viện phụ thuộc","text":"Thư viện hoặc công cụ mà code của bạn cần để chạy. Giữ chúng luôn được cập nhật rất quan trọng cho sự an toàn.","also":["software dependencies","software dependency"]},{"id":"package","g":"build","word":"Gói (package)","text":"Một bó code viết sẵn mà bạn có thể cài và dùng trong dự án.","also":["packages","package"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Trình quản lý gói","text":"Công cụ tải và cập nhật các gói mà code của bạn cần. npm là một công cụ phổ biến.","also":["package managers","npm","package manager"]},{"id":"git","g":"build","word":"Git","text":"Công cụ được dùng nhiều nhất để lưu lịch sử các thay đổi của code, dưới dạng commit và nhánh."},{"id":"github","g":"build","word":"GitHub","text":"Trang web lưu các kho Git trên mạng, để các nhóm chia sẻ code, xem lại thay đổi và theo dõi công việc."},{"id":"vcs","g":"build","word":"Quản lý phiên bản","text":"Lưu đầy đủ lịch sử mọi thay đổi của các tệp, để biết ai đã sửa gì và quay lại được khi cần. Git làm việc này.","also":["source control","version control system","version control"]},{"id":"clone","g":"build","word":"Clone (sao chép về máy)","text":"Tạo bản sao đầy đủ của riêng bạn về một kho code, kèm lịch sử, trên máy tính của bạn.","also":["cloned","cloning","clone"]},{"id":"pull","g":"build","word":"Pull (kéo về)","text":"Lấy các commit mới nhất từ bản dùng chung (như GitHub) về máy tính của bạn. Ngược lại với push.","also":["git pull","pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Nhánh chính","text":"Phiên bản chính thức của code mà mọi người cùng làm từ đó, thường tên là main hoặc master.","also":["master branch","main branch"]},{"id":"conflict","g":"build","word":"Xung đột khi gộp (merge conflict)","text":"Khi hai thay đổi đụng vào cùng những dòng theo cách khác nhau, nên máy tính không ghép được và một người phải chọn.","also":["merge conflicts","merge conflict"]},{"id":"diff","g":"build","word":"Diff (phần khác biệt)","text":"Màn hình cho thấy chính xác điều gì đã đổi giữa hai phiên bản: dòng được thêm và dòng bị bỏ đi.","also":["diffs","diff"]},{"id":"fork","g":"build","word":"Fork (nhân bản kho)","text":"Bản sao riêng của bạn từ kho code của người khác, bạn sửa thoải mái mà không ảnh hưởng đến bản gốc của họ.","also":["forks","forked","fork"]},{"id":"script","g":"build","word":"Script (tập lệnh)","text":"Một chương trình ngắn tự làm một việc, như dọn tệp hay khởi động ứng dụng.","also":["scripts","script","kịch bản"],"noTip":1},{"id":"build","g":"build","word":"Build (đóng gói)","text":"Biến code thành thứ sẵn sàng chạy, hoặc chính kết quả sẵn sàng chạy đó.","also":["builds","build"],"noTip":1},{"id":"compile","g":"build","word":"Biên dịch (compile)","text":"Dịch code do con người viết thành dạng mà máy tính chạy trực tiếp được.","also":["compiler","compile"]},{"id":"cli","g":"build","word":"Dòng lệnh (CLI)","text":"Một cửa sổ chữ nơi bạn gõ chỉ dẫn cho máy tính thay vì bấm chuột. Còn gọi là terminal.","also":["command line","command-line","CLI","terminal","cửa sổ dòng lệnh"]},{"id":"config","g":"build","word":"Cấu hình (config)","text":"Các thiết lập điều khiển cách phần mềm hoạt động, được tách khỏi code để dễ thay đổi.","also":["config","configuration","cài đặt cấu hình"],"noTip":1},{"id":"envvar","g":"build","word":"Biến môi trường","text":"Một thiết lập được đưa cho chương trình khi nó khởi động, thường dùng cho địa chỉ hoặc mật khẩu để không phải viết thẳng vào code.","also":["environment variables","env var","environment variable"]},{"id":"debugging","g":"build","word":"Gỡ lỗi (debug)","text":"Truy tìm vì sao một thứ không chạy, rồi sửa nó.","also":["debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Lập trình cặp","text":"Hai người (hoặc một người và một AI) cùng làm trên một đoạn code, một người gõ và một người kiểm tra.","also":["pairing","pair programming"]},{"id":"docs","g":"build","word":"Tài liệu (docs)","text":"Những bài viết giải thích một thứ hoạt động ra sao hoặc cách dùng nó.","also":["documentation","docs","tài liệu hướng dẫn"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Tệp đầu tiên nên đọc trong một kho code: dự án là gì và cách chạy nó.","also":["READMEs","tệp README"]},{"id":"legacy","g":"build","word":"Hệ thống cũ (legacy)","text":"Hệ thống cũ vẫn đang dùng và khó thay đổi, thường vì còn rất ít người hiểu nó.","also":["legacy systems","legacy code","legacy system"]},{"id":"techdebt","g":"build","word":"Nợ kỹ thuật","text":"Những lối tắt giúp tiết kiệm thời gian bây giờ nhưng làm các thay đổi sau này chậm hơn, như khoản vay cứ chồng thêm lãi. Dọn lại code (refactor) là cách trả nợ.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Bước kiểm tra xem một thứ có chạy đúng như mong muốn không. Có bài test do máy tính tự chạy mỗi khi code thay đổi; có bài là bạn tự thử một thẻ đã xong trước khi chấp nhận nó.","also":["tests","kiểm thử"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Viết tắt của quality assurance (đảm bảo chất lượng): mọi việc làm để chắc chắn công việc đúng trước khi đưa lên. Trong AI-gile, đó là các bước kiểm tra tự động: khi QA đỏ nghĩa là có thứ hỏng, và không thể đưa lên cho đến khi sửa xong.","also":["kiểm tra chất lượng","đảm bảo chất lượng","quality assurance","quality checks"]},{"id":"testpile","g":"test","word":"Chồng thử","text":"Các thẻ đã xong đang chờ bạn thử, lần lượt từng cái. Chấp nhận một thẻ hoặc gửi trả kèm ghi chú, và thẻ tiếp theo hiện lên.","also":["test pile","test piles"]},{"id":"autotest","g":"test","word":"Kiểm thử tự động","text":"Bài kiểm tra do máy tính tự chạy mỗi khi code thay đổi, để bắt lỗi sớm.","also":["automated tests","automatic tests","automated test"]},{"id":"manualtest","g":"test","word":"Kiểm thử thủ công","text":"Một người tự tay thử công việc để xem nó có hoạt động đúng như mong muốn không.","also":["manual tests","manual testing","manual test"]},{"id":"unittest","g":"test","word":"Kiểm thử đơn vị (unit test)","text":"Bài kiểm tra tự động nhỏ cho riêng một phần code rất nhỏ.","also":["unit tests","unit test"]},{"id":"integtest","g":"test","word":"Kiểm thử tích hợp","text":"Bài kiểm tra xem nhiều phần có hoạt động đúng khi ghép với nhau, chứ không chỉ từng phần một.","also":["integration tests","integration test"]},{"id":"endtoend","g":"test","word":"Kiểm thử đầu cuối (E2E)","text":"Bài kiểm tra đóng vai người dùng thật từ đầu đến cuối, như đăng ký, mua hàng và thanh toán.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Kiểm thử chấp nhận của người dùng (UAT)","text":"Chính những người đã đề nghị công việc tự thử và cho biết nó có đáp ứng nhu cầu của họ không. Chồng thử của AI-gile là phiên bản của việc này.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Hồi quy (regression)","text":"Thứ trước đây chạy tốt nhưng bị hỏng sau một thay đổi. Kiểm thử hồi quy xác nhận những thứ cũ vẫn chạy.","also":["regressions","regression test","regression tests","regression testing","lỗi hồi quy"]},{"id":"smoke","g":"test","word":"Kiểm thử nhanh (smoke test)","text":"Bài kiểm tra rất nhanh xem những thứ chính có chạy được không, ví dụ ngay sau khi một thay đổi được đưa lên. Nếu hỏng thì dừng lại và xem xét.","also":["smoke tests","smoke test"]},{"id":"exploratory","g":"test","word":"Kiểm thử khám phá","text":"Dùng thử sản phẩm một cách tự do, chọc ngoáy theo nhiều cách để tìm những lỗi mà các bài kiểm tra có kế hoạch bỏ sót.","also":["exploratory test","exploratory tests","exploratory testing"]},{"id":"testcase","g":"test","word":"Ca kiểm thử (test case)","text":"Một kịch bản được viết ra để thử: các bước và kết quả đáng lẽ phải có.","also":["test cases","test case"]},{"id":"coverage","g":"test","word":"Độ phủ kiểm thử","text":"Bao nhiêu phần của code được kiểm tra bằng các bài test tự động. Nhiều thường an toàn hơn, nhưng độ phủ cao thôi chưa chứng minh nó chạy tốt.","also":["code coverage","test coverage"]},{"id":"testdata","g":"test","word":"Dữ liệu thử","text":"Thông tin ví dụ tự bịa ra dùng khi kiểm thử, để không lộ thông tin riêng tư của người thật.","also":["test fixtures","test data"]},{"id":"edgecase","g":"test","word":"Trường hợp biên","text":"Tình huống bất thường ở giới hạn, như một biểu mẫu trống hay một cái tên có dấu nháy, nơi mọi thứ hay hỏng.","also":["edge cases","edge case"]},{"id":"happypath","g":"test","word":"Luồng suôn sẻ (happy path)","text":"Đường đi bình thường khi mọi thứ đều đúng. Kiểm thử tốt cũng thử cả những đường không suôn sẻ."},{"id":"perftest","g":"test","word":"Kiểm thử hiệu năng","text":"Kiểm tra một thứ nhanh đến đâu và chịu áp lực tốt đến đâu.","also":["performance test","performance tests","performance testing"]},{"id":"loadtest","g":"test","word":"Kiểm thử tải","text":"Kiểm tra hệ thống xoay xở thế nào khi rất nhiều người dùng cùng lúc.","also":["load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Kiểm thử bảo mật","text":"Tìm các điểm yếu có thể khiến ai đó lạm dụng hệ thống hoặc xem được thứ không được xem.","also":["security test","security tests","security testing"]},{"id":"accesstest","g":"test","word":"Kiểm thử khả năng tiếp cận","text":"Kiểm tra xem những người có khả năng khác nhau có dùng được sản phẩm không, kể cả bằng trình đọc màn hình hoặc chỉ bằng bàn phím.","also":["accessibility test","accessibility testing"]},{"id":"linting","g":"test","word":"Linting (soát lỗi code)","text":"Bước kiểm tra tự động phát hiện những lỗi có thể có và cách viết lộn xộn trong code, giống như công cụ soát chính tả cho chương trình.","also":["linter","lint","linting"]},{"id":"static","g":"test","word":"Phân tích tĩnh","text":"Kiểm tra code để tìm vấn đề bằng cách tự động đọc nó mà không chạy.","also":["static code analysis","static analysis"]},{"id":"flaky","g":"test","word":"Test chập chờn (flaky test)","text":"Bài test lúc đạt lúc hỏng mà không rõ lý do, nên không thể hoàn toàn tin được.","also":["flaky tests","flaky test"]},{"id":"repro","g":"test","word":"Tái hiện lỗi (repro)","text":"Cố ý làm lỗi xảy ra lại bằng cách làm theo cùng các bước, để có thể nghiên cứu và sửa. Viết các bước đó ra là phần hữu ích nhất của một báo cáo lỗi.","also":["repro","reproduce","steps to reproduce","các bước tái hiện"]},{"id":"severity","g":"test","word":"Mức độ nghiêm trọng","text":"Mức độ tồi tệ của ảnh hưởng do một vấn đề gây ra, từ chỉ hơi phiền đến mọi thứ ngừng hoạt động.","also":["severity level","severity"]},{"id":"deploy","g":"change","word":"Deploy","text":"Chép phiên bản mới của phần mềm lên các máy tính chạy nó, như bản thử hoặc dịch vụ đang chạy thật."},{"id":"release","g":"change","word":"Bản phát hành","text":"Một gói công việc đã xong, có tên, được đưa vào hoạt động cùng lúc, kèm ghi chú ngắn về những gì đã thay đổi. 🚀 Bản phát hành tự viết ghi chú từ các thẻ đã xong.","also":["phát hành","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Quay về phiên bản cuối cùng còn chạy tốt khi bản mới gây rắc rối. Trong AI-gile, nút Hoàn tác gom các bước hoàn tác ghi trên mỗi thay đổi thành một danh sách kiểm tra.","also":["quay lại bản cũ","hoàn tác","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"Phiên bản thật mà mọi người đang dùng, khác với bản sao để thử nghiệm. Đưa thứ gì lên đó gọi là đưa vào hoạt động. Lập trình viên còn gọi nó là production.","also":["production","bản chạy thật","môi trường thật"],"noTip":1},{"id":"change","g":"change","word":"Thay đổi","text":"Một thay đổi có kế hoạch cho thứ mà mọi người đang dựa vào, được ghi ra trước: làm gì, vì sao, rủi ro, khi nào và cách hoàn tác. Bắt đầu bằng 🔀 Đề xuất thay đổi.","also":["yêu cầu thay đổi","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Rủi ro","text":"Điều có thể xảy ra sai, được chấm điểm theo khả năng xảy ra và mức độ tệ. ⚠️ Rủi ro gom chúng vào một danh sách, điểm cao nhất lên đầu, mỗi cái có một ngày để xem lại.","also":["các rủi ro","sổ rủi ro","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"Khung giờ thay đổi","text":"Những khoảng thời gian được phép đưa thay đổi vào hoạt động, ví dụ một tối thứ Ba yên ắng. Ngoài khung giờ, thẻ thay đổi không thể hoàn tất, trừ khi là trường hợp khẩn cấp.","also":["change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Lần kiểm tra cuối ngay trước khi một thay đổi được đưa lên: mỗi người phải duyệt đều nói Go hoặc No go. Chỉ khi mọi người nói Go thì mới tiến hành.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Phê duyệt","text":"Chờ một cái gật đầu trước khi bắt đầu làm. Thẻ do bạn bè tạo, hoặc một thay đổi, sẽ chờ trong ✅ Phê duyệt cho đến khi bạn duyệt hoặc từ chối.","also":["duyệt","approval","approvals"]},{"id":"quiettime","g":"change","word":"Giờ yên tĩnh","text":"Một khoảng thời gian, như lúc phát trực tiếp, trình diễn hoặc ban đêm, khi không có gì được đưa lên. Các nhóm vẫn làm việc và kiểm thử, nhưng việc đưa lên phải đợi đến khi hết giờ. Ở nơi khác gọi là change freeze (đóng băng thay đổi).","also":["đóng băng thay đổi","quiet time","quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Cách làm việc mà người xây phần mềm và người vận hành nó làm như một nhóm, với nhiều tự động hóa, để thay đổi được đưa lên thường xuyên và an toàn."},{"id":"cicd","g":"change","word":"CI/CD (tích hợp và triển khai liên tục)","text":"Thay đổi của mọi người được gộp vào bản chính thường xuyên và kiểm tra tự động mỗi lần (tích hợp liên tục), nên phần mềm luôn sẵn sàng đưa lên chỉ bằng một cú bấm nút (phân phối liên tục).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Triển khai liên tục","text":"Tiến thêm một bước so với phân phối liên tục: mọi thay đổi vượt qua các bước kiểm tra đều tự động được đưa lên, không cần bấm nút.","also":["continuous deployments","continuous deployment"]},{"id":"pipeline","g":"change","word":"Pipeline (đường ống)","text":"Chuỗi các bước tự động mà một thay đổi đi qua trên đường được đưa lên, như build, test rồi triển khai.","also":["pipelines","pipeline"]},{"id":"environment","g":"change","word":"Môi trường","text":"Một bản sao riêng của hệ thống cho một mục đích, như một bản để xây dựng, một bản để thử và bản đang chạy thật.","also":["environments","environment"],"noTip":1},{"id":"devenv","g":"change","word":"Môi trường phát triển","text":"Bản sao mà lập trình viên làm việc trong đó, thường ngay trên máy của họ, nơi làm hỏng cũng chẳng hại ai.","also":["dev environment","development environment"]},{"id":"testenv","g":"change","word":"Môi trường thử nghiệm","text":"Một bản sao riêng của hệ thống chỉ dùng để kiểm thử, để không đụng đến dịch vụ thật.","also":["test environments","test environment"]},{"id":"staging","g":"change","word":"Môi trường staging","text":"Bản sao cuối cùng được dựng giống hệt bản chạy thật, để kiểm tra lần chót trước khi một thay đổi được đưa lên.","also":["staging environment","staging","môi trường chạy thử"]},{"id":"artifact","g":"change","word":"Sản phẩm build","text":"Tệp hoặc gói do một lần build tạo ra, sẵn sàng để lưu, kiểm tra hoặc đưa lên chạy thật.","also":["build artifacts","build artifact"]},{"id":"hotfix","g":"change","word":"Hotfix (sửa nóng)","text":"Bản sửa khẩn được đưa lên nhanh, ngoài kế hoạch thông thường, vì có thứ quan trọng đang hỏng.","also":["hotfixes","hotfix"]},{"id":"patch","g":"change","word":"Bản vá (patch)","text":"Một bản cập nhật nhỏ sửa lỗi hoặc bịt lỗ hổng bảo mật. Vá bảo mật nhanh chóng rất quan trọng.","also":["patches","security patch","security patches","patch"]},{"id":"version","g":"change","word":"Số phiên bản","text":"Nhãn như 2.4.1 cho biết bạn đang dùng bản phát hành nào. Thường số đầu đổi khi có thay đổi lớn, còn số cuối đổi khi sửa nhỏ.","also":["version numbers","semantic versioning","version number"]},{"id":"relnotes","g":"change","word":"Ghi chú phát hành","text":"Danh sách ngắn, dễ hiểu về những gì đã đổi trong một bản phát hành, dành cho người dùng, gồm các bản sửa và giới hạn đã biết. Còn gọi là changelog.","also":["changelog","change log","release notes"]},{"id":"flag","g":"change","word":"Công tắc tính năng (feature flag)","text":"Công tắc bật tắt cho một tính năng, để việc mới có thể đưa lên ở dạng ẩn rồi bật (hoặc tắt lại) mà không cần phát hành bản mới.","also":["feature flags","feature toggle","feature toggles","feature flag"]},{"id":"rollfwd","g":"change","word":"Sửa tiến (roll forward)","text":"Sửa một bản phát hành lỗi bằng cách nhanh chóng đưa lên một bản mới đã sửa, thay vì quay về bản cũ.","also":["rolling forward","rolled forward","roll forward"]},{"id":"canary","g":"change","word":"Phát hành thử nghiệm (canary)","text":"Đưa thay đổi lên cho một nhóm nhỏ trước, rồi chỉ đưa cho tất cả mọi người khi thấy ổn. Tên lấy từ những con chim hoàng yến thợ mỏ mang xuống hầm để cảnh báo sớm.","also":["canary releases","canary","canary release"]},{"id":"bluegreen","g":"change","word":"Triển khai xanh-lục (blue-green)","text":"Giữ hai bản của hệ thống đang chạy và chuyển mọi người sang bản mới cùng một lúc, nên nếu hỏng có thể chuyển ngược lại ngay.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Triển khai không gián đoạn","text":"Đưa phiên bản mới lên mà dịch vụ không bao giờ phải dừng đối với người dùng.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Quản lý thay đổi","text":"Giúp các thay đổi thành công: cân nhắc rủi ro, xin đúng sự phê duyệt và chọn thời điểm tốt. Còn gọi là change management.","also":["change management","change enablement"]},{"id":"cab","g":"change","word":"Hội đồng thẩm định thay đổi (CAB)","text":"Nhóm xem xét các thay đổi quan trọng và thống nhất có cho tiến hành không và khi nào.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Thay đổi tiêu chuẩn","text":"Thay đổi rủi ro thấp, lần nào cũng làm theo cùng một cách đã được kiểm chứng, nên được duyệt trước.","also":["standard changes","standard change"]},{"id":"normchange","g":"change","word":"Thay đổi thông thường","text":"Thay đổi cần được kiểm tra và phê duyệt trước khi tiến hành.","also":["normal changes","normal change"]},{"id":"emergchange","g":"change","word":"Thay đổi khẩn cấp","text":"Thay đổi phải làm ngay để sửa hoặc ngăn sự cố nghiêm trọng, với cách phê duyệt nhanh hơn tương ứng.","also":["emergency changes","emergency change"]},{"id":"automation","g":"change","word":"Tự động hóa","text":"Để máy tính tự làm một việc lặp đi lặp lại, nên nhanh hơn và lần nào cũng làm giống nhau.","also":["automated","automation"],"noTip":1},{"id":"infra","g":"change","word":"Hạ tầng","text":"Các máy, mạng và dịch vụ mà phần mềm chạy trên đó.","also":["infra","infrastructure","cơ sở hạ tầng"]},{"id":"iac","g":"change","word":"Hạ tầng dưới dạng code (IaC)","text":"Mô tả máy chủ và cài đặt của bạn trong các tệp lưu cùng với code, nên có thể dựng lại y hệt mỗi lần.","also":["IaC"]},{"id":"cloud","g":"change","word":"Đám mây (cloud)","text":"Thuê máy tính, chỗ lưu trữ và dịch vụ từ một nhà cung cấp lớn qua internet, thay vì tự sở hữu máy.","also":["the cloud","cloud computing","điện toán đám mây"]},{"id":"provider","g":"change","word":"Nhà cung cấp đám mây","text":"Công ty cho thuê tài nguyên máy tính qua internet, như Amazon Web Services (AWS), Microsoft Azure hay Google Cloud.","also":["cloud providers","cloud provider"]},{"id":"hosting","g":"change","word":"Hosting (lưu trữ web)","text":"Nơi ứng dụng hoặc trang web của bạn nằm và chạy để mọi người truy cập được, thường thuê của một công ty.","also":["hosting"]},{"id":"domain","g":"change","word":"Tên miền","text":"Địa chỉ web mà mọi người gõ vào, như example.com. Bạn thuê theo năm nên phải gia hạn.","also":["domain names","domain","domain name"]},{"id":"dns","g":"change","word":"DNS","text":"Viết tắt của domain name system: cuốn danh bạ của internet, đổi một cái tên như example.com thành địa chỉ của đúng máy tính.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"Một gói niêm phong chứa ứng dụng và mọi thứ nó cần, nên chạy giống nhau trên mọi máy tính. Docker là công cụ nổi tiếng nhất.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Máy ảo (VM)","text":"Một máy tính giả chạy bên trong máy tính thật, để một máy lớn có thể đóng vai nhiều máy.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (không máy chủ)","text":"Chạy code mà không phải tự lo máy chủ nào: nhà cung cấp chạy khi cần và bạn trả tiền theo mức dùng."},{"id":"lb","g":"change","word":"Bộ cân bằng tải","text":"Thứ chia người truy cập ra nhiều máy chủ, để không máy nào bị quá tải.","also":["load balancers","load balancer"]},{"id":"cache","g":"change","word":"Bộ nhớ đệm (cache)","text":"Nơi lưu sẵn các kết quả gần đây ở gần tay, để không phải lấy hoặc tính lại cùng một thứ. Xóa nó đi có thể sửa được những trang trông bị cũ.","also":["caches","caching","cached","cache"]},{"id":"cdn","g":"change","word":"Mạng phân phối nội dung (CDN)","text":"Một mạng lưới máy chủ khắp thế giới giữ bản sao các trang và hình ảnh của bạn gần người truy cập, nên tải rất nhanh.","also":["CDN"]},{"id":"migration","g":"change","word":"Di chuyển dữ liệu (migration)","text":"Chuyển dữ liệu hoặc hệ thống từ nơi cũ sang nơi mới, hoặc cẩn thận đổi cách bố trí của cơ sở dữ liệu.","also":["migrations","database migration","migration"]},{"id":"service","g":"run","word":"Dịch vụ","text":"Thứ bạn làm ra mà mọi người dựa vào, như một trang web hay một ứng dụng, được chăm sóc để luôn chạy tốt. Đánh dấu “Dự án này là một dịch vụ” rồi ghi nó cung cấp gì, ai dùng và ai trực.","also":["các dịch vụ","service","services"]},{"id":"uptimepct","g":"run","word":"Thời gian hoạt động (uptime)","text":"Dịch vụ hoạt động bao nhiêu phần thời gian, thường tính theo phần trăm. 99,9% vẫn cho phép ngừng khoảng 43 phút mỗi tháng.","also":["uptime percentage","uptime"]},{"id":"uptime","g":"run","word":"Kiểm tra uptime","text":"Một lần kiểm tra tự động, vài phút một lần, xem dịch vụ của bạn còn phản hồi không. Nếu nó thất bại vài lần liên tiếp, AI-gile tự mở một thẻ sự cố.","also":["uptime checks","kiểm tra hoạt động"]},{"id":"statuspage","g":"run","word":"Trang trạng thái","text":"Một trang công khai cho biết dịch vụ có đang chạy không (xanh, cam hay đỏ) kèm cập nhật mới nhất, để người dùng tự xem thay vì phải hỏi.","also":["status page","status pages"]},{"id":"desk","g":"run","word":"Bàn dịch vụ","text":"Nơi tiếp nhận câu hỏi và báo cáo từ những người dùng dịch vụ của bạn. AI-gile xếp mỗi cái vào yêu cầu, sự cố hoặc ý tưởng, và báo cho bạn khi nó giống một thứ đã được báo trước đó.","also":["các bàn dịch vụ","bàn hỗ trợ","bàn","service desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Yêu cầu dịch vụ","text":"Ai đó xin một thứ bình thường, như tài khoản mới hay chút trợ giúp, chứ không phải báo có gì bị hỏng. Nó chờ tới lượt; sự cố luôn được ưu tiên trước.","also":["các yêu cầu dịch vụ","yêu cầu","service request","service requests"]},{"id":"incident","g":"run","word":"Sự cố","text":"Thứ đang hỏng hoặc không chạy đúng đối với những người đang dùng ngay lúc này, như trang web sập hoặc rất chậm. Thẻ sự cố 🔥 được chen lên đầu hàng: làm cho nó chạy lại được là việc trước hết.","also":["các sự cố","incident","incidents"]},{"id":"major","g":"run","word":"Sự cố lớn","text":"Một sự cố lớn: nhiều người bị ảnh hưởng, hoặc tiền bạc hay dữ liệu gặp nguy. Một nút bấm đưa mọi nhóm vào cuộc (swarm), đánh thức người đang trực và yêu cầu cập nhật trạng thái mỗi 30 phút.","also":["sự cố nghiêm trọng","major incident","major incidents"]},{"id":"oncall","g":"run","word":"Trực","text":"Là người trả lời khi có gì đó hỏng, kể cả ban đêm. Mỗi dịch vụ có một thành viên trực, người được đánh thức đầu tiên khi dịch vụ đó có sự cố.","also":["trực sự cố","người trực","on call","on-call"]},{"id":"replyby","g":"run","word":"Hạn trả lời","text":"Một thẻ được chờ câu trả lời đầu tiên bao lâu, ví dụ một giờ cho sự cố. Quá hạn thì thẻ hiện đồng hồ đỏ, để không có gì bị lặng lẽ bỏ quên. Còn gọi là response target.","also":["thời hạn trả lời","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"Tổng kết sự cố","text":"Một lần nhìn lại ngắn sau sự cố: chuyện gì đã xảy ra, điều gì đã giúp và cần thay đổi gì, không đổ lỗi cho ai. Không có nó thì không đóng được sự cố. Còn gọi là post-mortem.","also":["post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Vấn đề","text":"Nguyên nhân ẩn đằng sau một hay nhiều sự cố. Thẻ 🧩 vấn đề gom những sự cố cứ lặp lại, để tìm ra nguyên nhân và sửa dứt điểm.","also":["các vấn đề","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Nguyên nhân gốc","text":"Lý do thật khiến thứ gì đó hỏng, không chỉ là cái bạn thấy bị lỗi. Sửa nguyên nhân gốc thì sự cố không quay lại nữa.","also":["nguyên nhân gốc rễ","root cause","root causes"]},{"id":"workaround","g":"run","word":"Cách xử lý tạm","text":"Một cách giữ mọi thứ chạy cho đến khi có bản sửa thật, như khởi động lại thứ gì đó khi nó bị treo. Nó được ghi trên thẻ vấn đề để không ai phải tự mò lại.","also":["giải pháp tạm","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"Lỗi đã biết","text":"Một vấn đề đã hiểu nguyên nhân nhưng chưa sửa, thường có cách xử lý tạm được ghi lại. 🧩 Lỗi đã biết liệt kê chúng, để mọi người dùng cách xử lý tạm thay vì đào lại từ đầu.","also":["các lỗi đã biết","known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Hướng dẫn từng bước để sửa một kiểu rắc rối đã biết, để lần nào cũng làm giống nhau và nhanh. Sau một sự cố lớn, nhóm có thể đề xuất một runbook để bạn duyệt.","also":["runbooks","sổ tay xử lý"]},{"id":"ci","g":"run","word":"Mục cấu hình","text":"Một thứ mà dịch vụ của bạn dựa vào, như máy chủ, tên miền, chứng chỉ, khóa hoặc nhà cung cấp. 🗂️ Mục liệt kê chúng theo từng dịch vụ, để bạn thấy một sự cố ảnh hưởng tới đâu và thứ gì cần gia hạn hoặc sao lưu.","also":["các mục cấu hình","mục","configuration item","configuration items","CI"]},{"id":"expiry","g":"run","word":"Ngày hết hạn","text":"Ngày một thứ ngừng hoạt động nếu không được gia hạn, như chứng chỉ bảo mật của trang web hay địa chỉ web của nó. AI-gile theo dõi các ngày này và tạo một thẻ gia hạn cho từng thứ trước 30 ngày, để không có gì ngừng bất ngờ.","also":["các ngày hết hạn","hết hạn","theo dõi hết hạn","expiry date","expiry dates","expiry"]},{"id":"backup","g":"run","word":"Sao lưu","text":"Một bản sao dữ liệu của bạn được lưu từ trước, để dựa vào nếu có gì bị mất hay hỏng. AI-gile sao lưu các bảng của bạn mỗi ngày.","also":["bản sao lưu","backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Khôi phục","text":"Lấy dữ liệu lại từ bản sao lưu. Một bản sao lưu chỉ thật sự có giá trị khi bạn biết nó khôi phục được, nên thỉnh thoảng hãy thử.","also":["đã khôi phục","restore","restored"]},{"id":"svcreview","g":"run","word":"Rà soát dịch vụ","text":"Nhìn lại một tháng của một dịch vụ: sự cố đã mở và đã sửa, mọi người nhận được trả lời nhanh đến đâu, thời gian hoạt động và token đã dùng. Rà soát hàng tháng hiển thị điều này cho từng dịch vụ.","also":["các bản rà soát dịch vụ","rà soát hàng tháng","service review","monthly review"]},{"id":"accessreview","g":"run","word":"Rà soát quyền truy cập","text":"Cứ 90 ngày lại kiểm tra ai vẫn còn vào được: liên kết chia sẻ, vai trò của bạn bè, mật khẩu và khóa đã lưu. Bạn giữ hoặc gỡ từng cái, để quyền truy cập cũ không còn nằm lại.","also":["các bản rà soát quyền truy cập","access review","access reviews"]},{"id":"improvements","g":"run","word":"Danh sách cải tiến","text":"Mọi điều nhóm đã quyết định làm tốt hơn, gom về một chỗ: đề xuất từ retro, hành động từ các buổi rà soát và các bản sửa vấn đề, mỗi cái kèm trạng thái. Xem ở 📈 Cải tiến.","also":["các danh sách cải tiến","cải tiến","improvement list","improvements"]},{"id":"tokencap","g":"run","word":"Hạn mức token","text":"Giới hạn hàng tháng cho số token mà các agent của một dịch vụ được dùng. Ở mức 80% bạn nhận cảnh báo; ở 100% công việc chạy nền của chúng sẽ chờ sang tháng sau hoặc đến khi bạn nâng hạn mức.","also":["các hạn mức token","hạn mức token hàng tháng","token cap","token caps"]},{"id":"svcmgmt","g":"run","word":"Quản lý dịch vụ","text":"Mọi việc để giữ cho một dịch vụ hữu ích và chạy tốt với những người dựa vào nó, ngày này qua ngày khác.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Bộ hướng dẫn được dùng rộng rãi về quản lý dịch vụ tốt, gồm các việc như sự cố, vấn đề và thay đổi. Tên này trước đây là viết tắt của IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Quản lý dịch vụ CNTT (ITSM)","text":"Vận hành công nghệ như một dịch vụ cho con người, với cách xử lý rõ ràng cho yêu cầu, sự cố, thay đổi và cải tiến.","also":["ITSM"]},{"id":"managed","g":"run","word":"Dịch vụ được quản lý","text":"Dịch vụ do người khác vận hành và chăm sóc cho bạn, theo một thỏa thuận về mức độ nó phải chạy tốt.","also":["managed services","managed service"]},{"id":"svcowner","g":"run","word":"Chủ dịch vụ","text":"Người chịu trách nhiệm về toàn bộ một dịch vụ: chạy tốt đến đâu, tốn bao nhiêu và được cải tiến thế nào.","also":["service owners","service owner"]},{"id":"sla","g":"run","word":"Thỏa thuận mức dịch vụ (SLA)","text":"Lời hứa bằng văn bản với khách hàng về mức dịch vụ sẽ chạy tốt đến đâu, như “hoạt động 99,9% thời gian” hay “trả lời trong vòng một giờ”, thường có hoàn tiền nếu không giữ được.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Mục tiêu mức dịch vụ (SLO)","text":"Mục tiêu riêng của nhóm về mức một dịch vụ nên chạy tốt trong một khoảng thời gian, thường đặt chặt hơn SLA một chút cho an toàn.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Chỉ số mức dịch vụ (SLI)","text":"Số đo thực tế mà bạn đối chiếu với mục tiêu, như tỷ lệ lượt truy cập tải bình thường.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Độ sẵn sàng","text":"Mọi người có dùng được dịch vụ khi cần hay không, thường đo bằng uptime.","also":["high availability","availability"]},{"id":"downtime","g":"run","word":"Thời gian ngừng hoạt động (downtime)","text":"Khoảng thời gian dịch vụ không chạy hoặc bị tắt, dù có kế hoạch hay không.","also":["down time","downtime"]},{"id":"errorbudget","g":"run","word":"Ngân sách lỗi (error budget)","text":"Mức thất bại nhỏ mà mục tiêu độ tin cậy của bạn cho phép. Còn thừa thì bạn có thể mạo hiểm với các thay đổi; dùng hết thì phải chậm lại.","also":["error budgets","error budget"]},{"id":"outage","g":"run","word":"Sự cố ngừng dịch vụ (outage)","text":"Lúc dịch vụ ngừng hẳn hoặc hỏng nặng đối với người dùng.","also":["outages","outage"]},{"id":"degraded","g":"run","word":"Suy giảm chất lượng","text":"Vẫn chạy nhưng kém: chậm, hoặc một số phần không hoạt động.","also":["degraded service","degraded"]},{"id":"monitoring","g":"run","word":"Giám sát (monitoring)","text":"Tự động theo dõi một dịch vụ mọi lúc, để phát hiện vấn đề, tốt nhất là trước khi người dùng nhận ra.","also":["monitoring"]},{"id":"observability","g":"run","word":"Khả năng quan sát (observability)","text":"Từ bên ngoài, bạn biết được chuyện gì đang xảy ra bên trong hệ thống đến đâu, nhờ nhật ký, các con số và dấu vết của nó.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Nhật ký (log)","text":"Cuốn nhật ký ghi liên tục mà chương trình giữ về những gì nó đang làm, dùng để tìm ra điều gì đã sai.","also":["logs","logging","log"],"noTip":1},{"id":"trace","g":"run","word":"Dấu vết (trace)","text":"Bản ghi cách một yêu cầu đi qua các phần khác nhau của hệ thống, từng bước, cho thấy nó chậm ở đâu.","also":["traces","tracing","trace"]},{"id":"latency","g":"run","word":"Độ trễ","text":"Một thứ mất bao lâu để phản hồi, như thời gian chờ từ lúc bấm đến lúc trang hiện ra.","also":["latency"]},{"id":"alert","g":"run","word":"Cảnh báo","text":"Tin nhắn tự động báo có thứ cần chú ý, như trang web không phản hồi.","also":["alerts","alerting","alert"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Mệt mỏi vì cảnh báo","text":"Khi có quá nhiều cảnh báo đến mức mọi người bắt đầu phớt lờ, kể cả những cảnh báo quan trọng.","also":["alarm fatigue","alert fatigue"]},{"id":"dashboard","g":"run","word":"Bảng điều khiển (dashboard)","text":"Một màn hình cho thấy các con số và trạng thái quan trọng nhất trong một cái nhìn.","also":["dashboards","dashboard"],"noTip":1},{"id":"paging","g":"run","word":"Gọi khẩn (paging)","text":"Gọi điện hoặc đánh thức khẩn cấp người đang trực về một vấn đề.","also":["paged","paging"]},{"id":"escalation","g":"run","word":"Báo cáo lên cấp trên (escalation)","text":"Mời người giỏi hơn hoặc có thẩm quyền hơn vào khi vấn đề không giải quyết được ở cấp hiện tại, hoặc không đủ nhanh.","also":["escalate","escalated","escalation"]},{"id":"triage","g":"run","word":"Phân loại ưu tiên (triage)","text":"Nhanh chóng sắp xếp các vấn đề gửi đến theo mức khẩn cấp và quan trọng, để cái tệ nhất được xử lý trước.","also":["triaged","triage"]},{"id":"impact","g":"run","word":"Mức ảnh hưởng","text":"Một việc ảnh hưởng đến mọi người nhiều đến đâu: bao nhiêu người và nặng thế nào.","noTip":1},{"id":"urgency","g":"run","word":"Mức khẩn cấp","text":"Một việc cần được xử lý nhanh đến đâu. Mức ảnh hưởng và mức khẩn cấp cùng quyết định độ ưu tiên.","noTip":1},{"id":"plevels","g":"run","word":"Cấp ưu tiên (P1, P2…)","text":"Nhãn cho biết một vấn đề khẩn cấp đến đâu. P1 nghiêm trọng nhất và cần hành động ngay.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Hàng đợi ticket","text":"Danh sách các yêu cầu và sự cố đang chờ người nhận.","also":["ticket queues","ticket queue"]},{"id":"tiers","g":"run","word":"Tuyến một và tuyến hai","text":"Các cấp hỗ trợ: tuyến một nghe điện thoại và xử lý việc đơn giản; tuyến hai có kỹ năng sâu hơn cho việc khó hơn. Còn gọi là tier 1 và tier 2.","also":["first-line support","tier 1","tier 2","tuyến 1","tuyến 2"]},{"id":"ic","g":"run","word":"Người chỉ huy sự cố","text":"Một người dẫn dắt việc ứng phó với sự cố, để ai cũng biết ai quyết định và ai làm gì.","also":["incident commanders","incident commander"]},{"id":"responsetime","g":"run","word":"Thời gian phản hồi","text":"Mất bao lâu trước khi có người đầu tiên nhận một yêu cầu hoặc sự cố.","also":["response times","response time"]},{"id":"resolution","g":"run","word":"Thời gian giải quyết","text":"Mất bao lâu để xử lý xong hoàn toàn một yêu cầu hoặc sự cố, từ lúc báo đến lúc đã sửa.","also":["resolution times","time to resolve","resolution time"]},{"id":"mttr","g":"run","word":"Thời gian khôi phục trung bình (MTTR)","text":"Trung bình mất bao lâu để dịch vụ chạy lại sau khi hỏng. MTTR có thể hiểu hơi khác nhau, nên hãy nói rõ bạn đo cái gì.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Thời gian trung bình giữa hai lần hỏng (MTBF)","text":"Trung bình một dịch vụ chạy được bao lâu thì có thứ hỏng.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Cơ sở dữ liệu quản lý cấu hình (CMDB)","text":"Danh sách mọi thành phần cấu hình của bạn và cách chúng liên kết, để thấy cái gì phụ thuộc vào cái gì.","also":["CMDB"]},{"id":"asset","g":"run","word":"Tài sản","text":"Bất cứ thứ gì có giá trị mà bạn sở hữu hoặc trả tiền để vận hành dịch vụ, như một máy tính xách tay, giấy phép phần mềm hay tên miền.","also":["assets","asset"],"noTip":1},{"id":"capplan","g":"run","word":"Lập kế hoạch năng lực","text":"Bảo đảm sẽ đủ sức mạnh máy tính, chỗ lưu trữ và con người cho những gì sắp đến.","also":["capacity plan","capacity planning"]},{"id":"scaling","g":"run","word":"Mở rộng quy mô (scaling)","text":"Đáp ứng nhiều người dùng hơn bằng cách cho một máy mạnh hơn (scale up) hoặc thêm nhiều máy (scale out).","also":["scale up","scale out","scaling up","scaling out","scaling"]},{"id":"bcp","g":"run","word":"Duy trì hoạt động kinh doanh","text":"Các kế hoạch giữ cho những việc quan trọng tiếp tục khi có chuyện lớn xảy ra, như mất văn phòng, mất nhà cung cấp chủ chốt hay mất máy tính.","also":["business continuity plan","business continuity"]},{"id":"dr","g":"run","word":"Khôi phục sau thảm họa (DR)","text":"Kế hoạch và công cụ để đưa một dịch vụ trở lại sau chuyện nghiêm trọng, như mất cả một trung tâm dữ liệu.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Thời gian khôi phục mục tiêu (RTO)","text":"Thời gian dài nhất một dịch vụ được phép ngừng sau thảm họa trước khi phải chạy lại.","also":["RTO"]},{"id":"rpo","g":"run","word":"Điểm khôi phục mục tiêu (RPO)","text":"Bạn chịu mất được bao nhiêu dữ liệu gần đây, tính bằng thời gian. RPO một giờ nghĩa là sao lưu ít nhất mỗi giờ.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Dự phòng","text":"Có sẵn đồ dự trữ, như máy chủ thứ hai, để một chỗ hỏng không làm dịch vụ ngừng.","also":["redundancy"]},{"id":"failover","g":"run","word":"Failover (tự chuyển sang dự phòng)","text":"Tự chuyển sang hệ thống dự phòng khi hệ thống thường dùng hỏng.","also":["fail over","failover"]},{"id":"spof","g":"run","word":"Điểm hỏng duy nhất","text":"Một bộ phận mà khi hỏng thì kéo theo tất cả, vì không có đồ dự phòng.","also":["single points of failure","SPOF","single point of failure"]},{"id":"maintwin","g":"run","word":"Khung giờ bảo trì","text":"Thời gian có kế hoạch mà dịch vụ có thể tạm dừng hoặc chậm để bảo dưỡng, được báo trước cho người dùng.","also":["maintenance windows","planned maintenance","maintenance window"]},{"id":"handover","g":"run","word":"Bàn giao","text":"Chuyển công việc, kiến thức và trách nhiệm cho người hoặc nhóm khác, để không bị sót gì.","also":["handovers","handover"]},{"id":"kb","g":"run","word":"Cơ sở tri thức","text":"Tập hợp các bài hướng dẫn và câu trả lời, cho người dùng và cho nhóm.","also":["knowledge bases","knowledge base"]},{"id":"csat","g":"run","word":"Mức hài lòng của khách hàng (CSAT)","text":"Điểm do người dùng cho biết họ hài lòng đến đâu, thường hỏi sau khi một yêu cầu được đóng.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Nhà cung cấp","text":"Công ty bên ngoài mà bạn dựa vào, như nhà cung cấp hosting. Còn gọi là vendor hoặc bên thứ ba.","also":["suppliers","vendor","vendors","third party","bên thứ ba"],"noTip":1},{"id":"retire","g":"run","word":"Ngừng cung cấp dịch vụ","text":"Tắt hẳn một dịch vụ một cách an toàn: báo cho người dùng, xử lý dữ liệu và quyền truy cập của nó, và cắt các khoản chi phí.","also":["retiring a service","service retirement"]},{"id":"eol","g":"run","word":"Hết vòng đời (EOL)","text":"Khi nhà sản xuất ngừng cập nhật hay hỗ trợ một sản phẩm, nên cần thay thế nó.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"An ninh mạng","text":"Bảo vệ hệ thống và dữ liệu khỏi bị đột nhập, đánh cắp hoặc phá hoại.","also":["cyber security","cybersecurity"]},{"id":"authn","g":"sec","word":"Xác thực","text":"Kiểm tra xem một người là ai, thường bằng mật khẩu hoặc một mã. Hay viết tắt là authn.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Phân quyền","text":"Kiểm tra một người được phép làm gì sau khi đã biết họ là ai. Hay viết tắt là authz.","also":["authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Xác thực nhiều lớp (MFA)","text":"Đăng nhập bằng hai hay nhiều bằng chứng, như mật khẩu cộng với một mã trên điện thoại. Còn gọi là xác thực hai lớp (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","xác thực hai lớp"]},{"id":"sso","g":"sec","word":"Đăng nhập một lần (SSO)","text":"Đăng nhập một lần để vào nhiều hệ thống, như dùng tài khoản công ty ở mọi nơi.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Trình quản lý mật khẩu","text":"Ứng dụng tạo mật khẩu mạnh và nhớ giúp bạn.","also":["password managers","password manager"]},{"id":"secret","g":"sec","word":"Bí mật (secret)","text":"Mật khẩu, khóa hoặc mã riêng khác mà chương trình dùng để vào một nơi nào đó. Tuyệt đối không được chia sẻ hay viết thẳng vào code.","also":["secrets","secret"],"noTip":1},{"id":"apikey","g":"sec","word":"Khóa API","text":"Mã bí mật cho phép một chương trình dùng API của dịch vụ khác, và cho biết ai đang dùng (và trả tiền) cho nó.","also":["API keys","API key"]},{"id":"accesstoken","g":"sec","word":"Mã truy cập (access token)","text":"Giấy thông hành tạm thời chứng minh một chương trình được phép vào, để không phải dùng mật khẩu của bạn mỗi lần. Không giống token của AI.","also":["access tokens","access token"]},{"id":"encryption","g":"sec","word":"Mã hóa","text":"Xáo trộn thông tin để chỉ người có đúng khóa mới đọc được.","also":["encrypted","encrypt","encryption"]},{"id":"https","g":"sec","word":"HTTPS","text":"Cách an toàn để các trang web được truyền đi, thể hiện bằng biểu tượng ổ khóa trên trình duyệt, để không ai ở giữa đọc hay sửa được."},{"id":"cert","g":"sec","word":"Chứng chỉ SSL/TLS","text":"Một chứng minh thư điện tử giúp trang web chứng minh mình là ai và dùng được HTTPS. Nó có hạn nên phải gia hạn.","also":["TLS certificate","SSL certificate","certificate","certificates","chứng chỉ số"]},{"id":"permissions","g":"sec","word":"Quyền truy cập","text":"Các quy tắc về ai được xem hoặc sửa cái gì.","also":["permission","permissions","phân quyền"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Quyền tối thiểu cần thiết","text":"Chỉ cấp cho mỗi người hay chương trình đúng quyền truy cập họ thật sự cần, và chỉ trong thời gian họ cần.","also":["principle of least privilege","least privilege"]},{"id":"rbac","g":"sec","word":"Phân quyền theo vai trò (RBAC)","text":"Cấp quyền theo vai trò, như người xem hay người chỉnh sửa, thay vì từng người một.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Lỗ hổng bảo mật","text":"Điểm yếu mà ai đó có thể lợi dụng để đột nhập hoặc gây hại.","also":["vulnerabilities","vulnerability"]},{"id":"zeroday","g":"sec","word":"Lỗ hổng zero-day","text":"Điểm yếu mà kẻ tấn công biết trước khi nhà sản xuất kịp có thời gian sửa.","also":["zero-days","zero day","zero-day"]},{"id":"malware","g":"sec","word":"Phần mềm độc hại","text":"Phần mềm gây hại, như virus, được tạo ra để phá hoại, theo dõi hoặc đánh cắp.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Mã độc tống tiền (ransomware)","text":"Mã độc khóa các tệp của bạn và đòi tiền để mở. Sao lưu tốt là cách phòng thủ hiệu quả nhất.","also":["ransomware attack","ransomware"]},{"id":"phishing","g":"sec","word":"Lừa đảo giả mạo (phishing)","text":"Những tin nhắn giả cố lừa bạn đưa mật khẩu hoặc tiền, hoặc mở thứ có hại.","also":["phishing email","phishing emails","phishing"]},{"id":"socialeng","g":"sec","word":"Tấn công phi kỹ thuật","text":"Lừa con người chứ không phải máy tính để họ cho phép truy cập, như một cuộc gọi giả từ “bộ phận hỗ trợ CNTT”."},{"id":"firewall","g":"sec","word":"Tường lửa","text":"Người gác cổng quyết định lưu lượng mạng nào được vào hoặc ra.","also":["firewalls","firewall"]},{"id":"vpn","g":"sec","word":"VPN","text":"Viết tắt của virtual private network (mạng riêng ảo): một đường kết nối riêng, được mã hóa, qua internet, thường dùng để vào hệ thống công ty một cách an toàn.","also":["virtual private network","mạng riêng ảo"]},{"id":"ddos","g":"sec","word":"Tấn công từ chối dịch vụ (DoS, DDoS)","text":"Dội vào một dịch vụ quá nhiều lưu lượng giả đến mức người thật không dùng được. DDoS nghĩa là từ nhiều máy tính cùng lúc.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Kiểm thử xâm nhập (pen test)","text":"Thuê các chuyên gia thiện chí thử đột nhập, để tìm ra điểm yếu trước khi kẻ tấn công thật tìm thấy.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Kiểm toán bảo mật","text":"Rà soát cẩn thận mức độ bảo vệ của một thứ, đối chiếu với danh sách thực hành tốt.","also":["security audits","security audit"]},{"id":"threatmodel","g":"sec","word":"Mô hình hóa mối đe dọa","text":"Nghĩ kỹ xem ai có thể tấn công một thứ, bằng cách nào, và bạn sẽ làm gì để ngăn họ.","also":["threat model","threat modeling","threat modelling"]},{"id":"breach","g":"sec","word":"Rò rỉ dữ liệu","text":"Khi thông tin riêng tư lọt ra cho những người không được có, hoặc bị mất hay bị sửa mà không được phép.","also":["data breaches","data breach"]},{"id":"pii","g":"sec","word":"Dữ liệu cá nhân","text":"Mọi thông tin về một người có thể nhận ra được, như tên, địa chỉ email hay vị trí. Còn gọi là PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Luật của châu Âu về dữ liệu cá nhân (Vương quốc Anh có phiên bản riêng): chỉ thu thập những gì cần, giữ an toàn, và cho người ta xem hoặc xóa dữ liệu của mình.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Bảo vệ dữ liệu","text":"Chăm sóc dữ liệu cá nhân đúng cách và đúng luật.","also":["data protection law","data protection"]},{"id":"privacypolicy","g":"sec","word":"Chính sách quyền riêng tư","text":"Một trang công khai nói bạn thu thập dữ liệu cá nhân nào, vì sao, và làm gì với nó.","also":["privacy statement","privacy notice","privacy policy"]},{"id":"consent","g":"sec","word":"Sự đồng ý","text":"Lời đồng ý rõ ràng, tự nguyện của một người cho phép dữ liệu của họ được dùng theo một cách cụ thể. Họ có thể rút lại bất cứ lúc nào.","also":["opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Một tệp nhỏ mà trang web lưu trong trình duyệt của bạn để nhớ mọi thứ, như việc bạn đã đăng nhập. Một số cần có sự đồng ý của bạn trước.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Giảm thiểu dữ liệu","text":"Chỉ thu thập và giữ những dữ liệu cá nhân thật sự cần cho công việc.","also":["data minimization","data minimisation"]},{"id":"retention","g":"sec","word":"Thời hạn lưu giữ dữ liệu","text":"Dữ liệu được giữ bao lâu trước khi bị xóa. Giữ không lâu hơn mức cần thiết thì an toàn hơn và thường là yêu cầu của luật.","also":["retention period","data retention"]},{"id":"anon","g":"sec","word":"Ẩn danh hóa","text":"Biến đổi dữ liệu để không ai còn có thể nhận ra một người từ nó một cách hợp lý.","also":["anonymised","anonymization","anonymous data","anonymisation"]},{"id":"pseudo","g":"sec","word":"Giả danh hóa","text":"Thay tên và các chi tiết khác bằng mã, còn khóa để nối lại được giữ riêng. Nó vẫn là dữ liệu cá nhân.","also":["pseudonymised","pseudonymization","pseudonymisation"]},{"id":"dpa","g":"sec","word":"Thỏa thuận xử lý dữ liệu (DPA)","text":"Hợp đồng nói nhà cung cấp được phép xử lý dữ liệu cá nhân thay mặt bạn như thế nào.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Đánh giá tác động bảo vệ dữ liệu (DPIA)","text":"Xem xét kỹ trước khi bắt đầu xem kế hoạch dùng dữ liệu cá nhân có thể ảnh hưởng đến mọi người ra sao và làm thế nào giảm rủi ro.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Nhật ký kiểm toán","text":"Bản ghi ai đã làm gì và khi nào, để có thể kiểm tra lại các hành động sau này.","also":["audit logs","audit trail","audit log"]},{"id":"compliance","g":"sec","word":"Tuân thủ","text":"Làm theo các luật, quy định và tiêu chuẩn áp dụng cho bạn, và chứng minh được là bạn làm vậy.","also":["compliant","compliance"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Một tiêu chuẩn quốc tế nổi tiếng về quản lý an toàn thông tin. Các công ty có thể được cấp chứng nhận theo tiêu chuẩn này.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Một báo cáo của Mỹ, do kiểm toán viên bên ngoài kiểm tra, cho thấy công ty chăm sóc dữ liệu khách hàng đúng cách.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI tự làm một nhiệm vụ: đọc code, sửa đổi, chạy kiểm tra rồi báo lại. Công việc của nó vẫn được kiểm tra.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Những mẩu chữ nhỏ mà AI đọc và viết, mỗi token khoảng ba phần tư một từ. Việc dùng AI được tính bằng token, nên ít token hơn thì gói của bạn còn nhiều hơn.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Một lệnh nhỏ tự chạy vào một thời điểm định sẵn, ví dụ khi một phiên AI bắt đầu, để nhóm nghe được bình luận của bạn.","also":["hooks"]},{"id":"ai","g":"ai","word":"Trí tuệ nhân tạo (AI)","text":"Các hệ thống máy tính làm những việc mà thường ta nghĩ cần con người, như viết, trả lời câu hỏi hay nhận ra hình ảnh.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Học máy (ML)","text":"Cách làm cho máy tính tự học các quy luật từ rất nhiều ví dụ, thay vì đưa cho nó các quy tắc chính xác.","also":["machine learning"]},{"id":"model","g":"ai","word":"Mô hình","text":"“Bộ não” đã được huấn luyện của một hệ thống AI, hình thành nhờ học từ vô số ví dụ. Các mô hình khác nhau về năng lực, tốc độ và giá.","also":["models","AI model","mô hình AI"],"noTip":1},{"id":"llm","g":"ai","word":"Mô hình ngôn ngữ lớn (LLM)","text":"Mô hình AI được huấn luyện trên lượng văn bản khổng lồ, nên đọc và viết được ngôn ngữ.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"AI tạo sinh","text":"AI tạo ra những thứ mới, như văn bản, hình ảnh hay code, chứ không chỉ phân loại hoặc nhận diện.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Chương trình bạn trò chuyện bằng ngôn ngữ đời thường, bằng cách gõ hoặc nói.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt (câu lệnh)","text":"Những gì bạn đưa cho AI: câu hỏi hoặc chỉ dẫn của bạn, cùng bất cứ thứ gì bạn trao cho nó. Prompt rõ ràng hơn thường cho câu trả lời tốt hơn.","also":["prompts","câu lệnh cho AI"]},{"id":"prompteng","g":"ai","word":"Kỹ thuật viết prompt","text":"Kỹ năng viết prompt để có kết quả đáng tin cậy và hữu ích.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Prompt hệ thống","text":"Những chỉ dẫn nền mà AI nhận trước khi cuộc trò chuyện bắt đầu, đặt vai trò và quy tắc cho nó. Chúng có trọng lượng hơn những gì bạn gõ.","also":["system prompts","system instruction","system instructions","system prompt"]},{"id":"context","g":"ai","word":"Ngữ cảnh (context)","text":"Mọi thứ AI nhìn thấy khi làm việc: các chỉ dẫn, tin nhắn của bạn, các tệp nó đã đọc và những câu trả lời trước.","noTip":1},{"id":"ctxwin","g":"ai","word":"Cửa sổ ngữ cảnh","text":"AI có thể nhớ cùng lúc được bao nhiêu, đo bằng token. Vượt quá mức đó, các phần cũ hơn sẽ bị bỏ hoặc tóm tắt lại.","also":["context windows","context window"]},{"id":"session","g":"ai","word":"Phiên làm việc","text":"Một cuộc trò chuyện làm việc với AI, từ đầu đến cuối. Phiên mới bắt đầu với bộ nhớ trống.","also":["sessions","session"],"noTip":1},{"id":"memory","g":"ai","word":"Bộ nhớ","text":"Những ghi chú AI giữ giữa các phiên, để nó nhớ sở thích và các quyết định trước đây của bạn.","noTip":1},{"id":"hallucination","g":"ai","word":"Ảo giác (hallucination)","text":"Khi AI nói điều nghe rất tự tin nhưng thật ra là bịa hoặc sai. Hãy kiểm tra lại những thông tin quan trọng.","also":["hallucinations","hallucinate","hallucinates","hallucination"]},{"id":"training","g":"ai","word":"Huấn luyện","text":"Dạy một mô hình bằng cách cho nó xem vô số ví dụ, trước khi có ai dùng.","also":["trained","training"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Dữ liệu huấn luyện","text":"Những ví dụ mà mô hình đã học. Kiến thức của nó dừng ở ngày dữ liệu đó được thu thập.","also":["training set","training data"]},{"id":"cutoff","g":"ai","word":"Mốc kiến thức cuối cùng","text":"Ngày mà kiến thức có sẵn của AI kết thúc. Nó sẽ không biết chuyện xảy ra sau đó, trừ khi nó tra cứu.","also":["training cutoff","knowledge cutoff"]},{"id":"finetune","g":"ai","word":"Tinh chỉnh (fine-tuning)","text":"Huấn luyện thêm một mô hình có sẵn bằng các ví dụ của riêng bạn, để nó giỏi hơn ở một việc cụ thể.","also":["fine-tune","fine-tuned","fine tuning","fine-tuning"]},{"id":"inference","g":"ai","word":"Suy luận (inference)","text":"Việc một mô hình AI thật sự được dùng để trả lời điều gì đó, khác với lúc nó được huấn luyện.","also":["model inference","inference"]},{"id":"tooluse","g":"ai","word":"Dùng công cụ","text":"Việc AI làm được nhiều thứ chứ không chỉ nói chuyện: chạy lệnh, đọc tệp hay tìm trên web, thông qua các công cụ mà ứng dụng trao cho nó.","also":["tool calling","tool call","tool calls","tool use"]},{"id":"subagent","g":"ai","word":"Agent phụ (subagent)","text":"AI trợ giúp mà AI chính giao cho một việc nhỏ hơn rồi nhận lại kết quả.","also":["subagents","sub-agent","subagent"]},{"id":"multiagent","g":"ai","word":"Nhiều agent (multi-agent)","text":"Nhiều AI cùng làm một công việc, mỗi AI một phần, giống như một nhóm nhỏ.","also":["multi-agent system","multi-agent"]},{"id":"autonomy","g":"ai","word":"Mức tự chủ","text":"AI được tự làm bao nhiêu việc trước khi phải hỏi một con người.","also":["autonomous","autonomy"]},{"id":"hitl","g":"ai","word":"Con người trong vòng lặp","text":"Luôn có một người tham gia để kiểm tra hoặc duyệt việc AI làm ở những điểm then chốt. Trong AI-gile, đó là bạn.","also":["human-in-the-loop","HITL","human in the loop"]},{"id":"guardrails","g":"ai","word":"Lan can an toàn (guardrails)","text":"Các giới hạn và bước kiểm tra giữ cho hành động của AI an toàn, như cần được duyệt trước khi bất cứ thứ gì được đưa lên. Chúng giảm nguy cơ sai sót nhưng không loại trừ hoàn toàn.","also":["guardrail","guardrails"]},{"id":"rag","g":"ai","word":"Tạo sinh tăng cường truy xuất (RAG)","text":"Cho AI tra cứu trong tài liệu của riêng bạn trước khi trả lời, để câu trả lời dựa trên thông tin của bạn.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (vector hóa văn bản)","text":"Biến văn bản thành một dãy số nắm giữ ý nghĩa của nó, để máy tính tìm được những thứ có nghĩa tương tự.","also":["embeddings","embedding"]},{"id":"vectordb","g":"ai","word":"Cơ sở dữ liệu vector","text":"Cơ sở dữ liệu được tạo ra để tìm trong những dãy số đó (embedding), nhằm tìm tài liệu có ý nghĩa tương tự.","also":["vector databases","vector store","vector database"]},{"id":"mcp","g":"ai","word":"Giao thức ngữ cảnh mô hình (MCP)","text":"Một cách chung để cắm công cụ và nguồn dữ liệu vào các ứng dụng AI, để AI dùng được chúng.","also":["MCP","Model Context Protocol"]},{"id":"temperature","g":"ai","word":"Nhiệt độ (temperature)","text":"Một thiết lập cho biết câu trả lời của AI phiêu lưu đến đâu. Thấp thì ổn định, dễ đoán hơn; cao thì đa dạng hơn. Không cái nào bảo đảm nó luôn đúng.","also":["model temperature","temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Đa phương thức (multimodal)","text":"Làm việc được với nhiều hơn một loại thông tin, như văn bản, hình ảnh và âm thanh.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Đánh giá (eval)","text":"Bài kiểm tra có kế hoạch xem AI làm tốt đến đâu trên các ví dụ đã chọn, để so sánh các mô hình hoặc prompt.","also":["eval","evals","evaluation"]},{"id":"bias","g":"ai","word":"Thiên kiến","text":"Khi một AI (hoặc một người) nghiêng về một phía một cách không công bằng, thường do những gì nó đã học.","also":["biased","bias"],"noTip":1},{"id":"responsible","g":"ai","word":"AI có trách nhiệm","text":"Dùng AI một cách công bằng, an toàn và trung thực, trong khi con người vẫn phải chịu trách nhiệm về kết quả.","also":["ethical AI","responsible AI"]},{"id":"injection","g":"ai","word":"Chèn prompt (prompt injection)","text":"Chiêu trò dùng chỉ dẫn ẩn trong trang web hay tệp để khiến AI làm điều người dùng nó không yêu cầu.","also":["prompt injections","prompt injection"]},{"id":"ratelimit","g":"ai","word":"Giới hạn tần suất (rate limit)","text":"Mức trần số yêu cầu bạn được gửi đến một dịch vụ trong một khoảng thời gian. Vượt quá thì phải chờ.","also":["rate limits","rate limited","rate limit"]},{"id":"usagelimit","g":"ai","word":"Giới hạn sử dụng","text":"Gói của bạn cho phép bao nhiêu việc AI trong một khoảng thời gian, sau đó nó tạm dừng hoặc tốn thêm tiền.","also":["usage limits","usage limit"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Làm phần mềm chủ yếu bằng cách mô tả điều bạn muốn cho AI rồi để nó viết code.","also":["vibe-coding","lập trình theo cảm hứng"]},{"id":"budget","g":"money","word":"Ngân sách","text":"Số tiền dành riêng cho một việc.","also":["budgets","budget"],"noTip":1},{"id":"costest","g":"money","word":"Ước tính chi phí","text":"Phỏng đoán tốt nhất về một việc sẽ tốn bao nhiêu trước khi bắt đầu.","also":["cost estimates","cost estimate"]},{"id":"roi","g":"money","word":"Lợi tức đầu tư (ROI)","text":"Bạn nhận lại được gì so với những gì bỏ vào. Nếu dương thì là đáng.","also":["ROI"]},{"id":"tco","g":"money","word":"Tổng chi phí sở hữu (TCO)","text":"Mọi khoản một thứ thật sự tốn trong cả vòng đời, không chỉ giá mua: vận hành, hỗ trợ, nâng cấp và cuối cùng là ngừng dùng.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx và OpEx","text":"CapEx là tiền chi một lần từ đầu cho những thứ bạn giữ lại; OpEx là khoản chi thường xuyên, như hóa đơn hằng tháng.","also":["CapEx","OpEx","capital expenditure","operating expenditure","chi phí đầu tư","chi phí vận hành"]},{"id":"subscription","g":"money","word":"Gói thuê bao","text":"Trả tiền định kỳ, thường hằng tháng hoặc hằng năm, để tiếp tục dùng một thứ.","also":["subscriptions","subscription","đăng ký dịch vụ"],"noTip":1},{"id":"saas","g":"money","word":"Phần mềm như một dịch vụ (SaaS)","text":"Phần mềm bạn dùng trực tuyến và trả tiền theo gói thuê bao, còn nhà sản xuất vận hành nó cho bạn.","also":["SaaS"]},{"id":"payg","g":"money","word":"Trả theo mức dùng","text":"Chỉ trả cho những gì bạn dùng, như điện toán đám mây hoặc token AI.","also":["pay-as-you-go","usage-based pricing","pay as you go"]},{"id":"overage","g":"money","word":"Phần dùng vượt mức","text":"Mức dùng vượt quá những gì gói của bạn bao gồm, có thể tốn thêm tiền.","also":["overages","overage charges","overage"]},{"id":"billingalert","g":"money","word":"Cảnh báo chi phí","text":"Tin nhắn khi chi tiêu hoặc mức dùng chạm mức bạn chọn. Nó cảnh báo bạn nhưng không phải lúc nào cũng chặn được các khoản phí tiếp theo.","also":["billing alerts","spending alert","billing alert"]},{"id":"freetier","g":"money","word":"Gói miễn phí","text":"Mức miễn phí của một dịch vụ trả phí, có giới hạn. Tiện cho lúc mới bắt đầu.","also":["free plan","free tier"]},{"id":"pricing","g":"money","word":"Gói giá","text":"Các gói khác nhau mà một dịch vụ bán, mỗi gói có giá và giới hạn riêng.","also":["pricing plans","price plan","pricing plan","bảng giá"]},{"id":"licence","g":"money","word":"Giấy phép sử dụng","text":"Các quy tắc về việc bạn được dùng, sao chép, sửa hay chia sẻ thứ người khác làm ra thế nào, như phần mềm, phông chữ hay hình ảnh.","also":["licences","license","licenses","licence","bản quyền sử dụng"],"noTip":1},{"id":"opensource","g":"money","word":"Mã nguồn mở","text":"Phần mềm mà ai cũng đọc được code, dùng được và thường sửa được miễn phí, theo quy định của giấy phép.","also":["open-source","open source software","OSS","open source"]},{"id":"osslicence","g":"money","word":"Giấy phép mã nguồn mở","text":"Các quy tắc đi kèm code mã nguồn mở. Có loại cho làm hầu như mọi thứ (như MIT); có loại yêu cầu bạn chia sẻ cả các thay đổi của mình (như GPL).","also":["open source licences","MIT licence","GPL","open source licence"]},{"id":"proprietary","g":"money","word":"Độc quyền (proprietary)","text":"Thuộc sở hữu của một công ty và không được tự do sao chép hay sửa. Trái ngược với mã nguồn mở.","also":["proprietary software","proprietary"]},{"id":"copyright","g":"money","word":"Bản quyền","text":"Quyền hợp pháp của người sáng tạo trong việc kiểm soát các bản sao tác phẩm của mình, kể cả code và bài viết.","also":["copyrighted","copyright"],"noTip":1},{"id":"ip","g":"money","word":"Sở hữu trí tuệ (IP)","text":"Ý tưởng và sáng tạo mà pháp luật coi là có chủ sở hữu, như code, thiết kế, tên và logo.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Điều khoản dịch vụ","text":"Các quy tắc bạn đồng ý khi dùng một dịch vụ.","also":["terms and conditions","terms of use","terms of service","điều khoản sử dụng"]},{"id":"contract","g":"money","word":"Hợp đồng","text":"Thỏa thuận bằng văn bản giữa hai bên mà pháp luật sẽ bảo vệ.","also":["contracts","contract"],"noTip":1},{"id":"sow","g":"money","word":"Bản mô tả công việc (SOW)","text":"Tài liệu nêu chính xác sẽ làm những việc gì, khi nào xong và với giá bao nhiêu.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Giá cố định","text":"Mức giá đã thỏa thuận cho cả công việc, dù mất bao lâu.","also":["fixed-price","fixed price","trọn gói"]},{"id":"tm","g":"money","word":"Tính theo giờ công và vật tư","text":"Trả tiền cho số giờ thật sự đã làm và những thứ thật sự đã dùng, thay vì một mức giá định sẵn.","also":["T&M","time and materials"]},{"id":"invoice","g":"money","word":"Hóa đơn","text":"Giấy đề nghị thanh toán cho công việc đã làm hoặc hàng đã giao.","also":["invoices","invoice"],"noTip":1},{"id":"lockin","g":"money","word":"Bị khóa chặt vào nhà cung cấp","text":"Khi việc rời một nhà cung cấp khó hoặc tốn kém đến mức bạn bị kẹt với họ.","also":["lock-in","vendor lock-in"]},{"id":"procurement","g":"money","word":"Mua sắm","text":"Quá trình chọn và mua hàng từ các nhà cung cấp.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Tín dụng dịch vụ","text":"Tiền hoàn lại hoặc giảm giá bạn nhận được khi nhà cung cấp không đạt SLA.","also":["service credits","service credit"]}]}};
